function residentFinance(id){const f=ensureFinance(),assets=data.locaties.filter(r=>r.ownerId===id),plots=(data.map?.plots||[]).filter(p=>p.ownerId===id),rules=assets.map(assetFinance),cells=new Set(plots.flatMap(plotCells).map(c=>c.join(','))).size,plotCount=cells/f.startPlotCells,plotCost=plotPurchaseValue(plotCount,f.plotPrices),income=rules.reduce((a,r)=>a+r.income,0),lodging=lodgingCost(data.inwoners.find(n=>n.id===id)),upkeep=rules.reduce((a,r)=>a+r.upkeep,0)+lodging,build=rules.reduce((a,r)=>a+r.build,0)+plotCost;return {assets,plots,income,upkeep,lodging,net:income-upkeep,value:build,build,plotCost,cells,plotCount}}

