function renderFinance(){if(player){view='kaart';render();return}const f=ensureFinance();if(data.map)for(const id of new Set(data.map.plots.map(p=>p.ownerId||'')))mergeOwnerPlots(id);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#heading').textContent='Kanselarij';$('#subtitle').textContent='Eigendom, verwachte opbrengst en kosten per campagneweek.';$('#add').hidden=true;$('#renameVillage').hidden=false;const residents=data.inwoners.filter(n=>financeOwner==='all'||n.id===financeOwner),totals=residents.map(n=>residentFinance(n.id));$('#stats').innerHTML=[['NETTO / WEEK',gp(totals.reduce((a,r)=>a+r.net,0))],['KOSTEN / WEEK',gp(totals.reduce((a,r)=>a+r.upkeep,0))],['TOTALE OMZET / WEEK',gp(totals.reduce((a,r)=>a+r.income,0))],[(financeOwner==='all'?'Waarde van '+data.villageName:'Waarde bezittingen').toUpperCase(),gp(financeOwner==='all'?data.locaties.reduce((a,r)=>a+assetFinance(r).build,0)+data.inwoners.reduce((a,n)=>a+residentFinance(n.id).plotCost,0):totals.reduce((a,r)=>a+r.value,0))]].map(([l,v])=>`<div class="stat"><b>${v}</b><span>${l}</span></div>`).join('');$('#content').innerHTML=`<div class="finance-toolbar"><label>Inwoner<select id="financeOwner"><option value="all">Alle inwoners</option>${data.inwoners.map(n=>`<option value="${esc(n.id)}" ${financeOwner===n.id?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label><div>${[['overview','Overzicht'],['buildings','Panden & percelen'],['rates','Tarieven'],['payouts','Betalingen'],['cashbook','Kasboek'],['registry','Akten']].map(([id,l])=>`<button data-finance-tab="${id}" class="${financeTab===id?'primary':''}">${l}</button>`).join('')}</div><button id="financeExport">↓ Exporteren</button></div><div id="financeBody"></div>`;
$('#financeOwner').onchange=e=>{financeOwner=e.target.value;render()};document.querySelectorAll('[data-finance-tab]').forEach(b=>b.onclick=()=>{financeTab=b.dataset.financeTab;render()});$('#financeExport').onclick=()=>$('#financeExportEditor').showModal();
if(financeTab==='registry'){renderCivilRegistry();return}if(['overview','buildings','plots'].includes(financeTab)){renderFinanceAssets(residents);splitFinanceAssets(financeTab);if(financeTab==='buildings')enhanceStaffing();}if(financeTab==='rates'){renderFinanceRates();addRateForms();enhanceRates();addLodgingRate();}if(financeTab==='cashbook')renderCashbookTab();else if(financeTab==='payouts')$('#financeBody').innerHTML='';else bindFinanceAutosave();}
function renderFinanceAssets(residents){const f=ensureFinance();$('#financeBody').innerHTML=`<div class="cards">${residents.map(n=>{const s=residentFinance(n.id);return `<article class="card finance-resident" data-resident-id="${esc(n.id)}">${n.portrait?`<img class="resident-portrait" src="${esc(n.portrait)}" alt="${esc(n.name)}">`:''}<h2>${esc(n.name)}</h2><p>${s.assets.length} panden · ${s.cells} perceelvakken</p><p><b>${gp(s.net)} netto / week</b><br>${gp(s.income)} opbrengst − ${gp(s.upkeep)} kosten</p><p>Eenmalige bouw & aanschaf: ${gp(s.build)}</p>${s.lodging?`<p>Overnachtingen: ${gp(s.lodging)} / week<br>${esc(lodgingName())} · ${gp(lodgingRate())} / nacht</p>`:''}<p><b>Percelen in bezit: ${s.plots.length}</b><br>${s.cells} vakjes. Grondwaarde: ${gp(s.plotCost)}.</p></article>`}).join('')}</div><h2>Panden en eigenaren</h2><p class="finance-note">Wonen of werken in een pand is geen eigendom. Wijs hieronder de eigenaar expliciet toe.</p><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Pand</th><th>Eigenaar</th><th>Regelprofiel</th><th>Personeel</th><th>Uitbreidingen</th><th>Omzet / week</th><th>Kosten / week</th><th>Pandwaarde</th></tr></thead><tbody>${data.locaties.filter(r=>financeOwner==='all'||r.ownerId===financeOwner||!r.ownerId).map(r=>{const s=assetFinance(r),rule=f.assets[r.id]||{};return `<tr><td>${esc(r.name)}<small>${esc(r.kind)}</small></td><td><select data-asset-owner="${esc(r.id)}">${ownerOptions(r.ownerId)}</select></td><td><select data-asset="${esc(r.id)}" data-field="profile">${f.catalog.filter(p=>!p.archived||p.id===s.profile.id).map(p=>`<option value="${p.id}" ${s.profile.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></td><td><select data-asset="${esc(r.id)}" data-field="staff" ${s.profile.workshop?'':'disabled'}>${f.staff.filter(p=>!p.archived||p.id===s.staff.id).map(p=>`<option value="${p.id}" ${s.staff.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></td><td><input type="number" min="0" max="100" step="1" data-asset="${esc(r.id)}" data-field="modules" ${s.profile.workshop?'':'disabled'} value="${s.modules}"></td>${[['incomeOverride',s.income],['upkeepOverride',s.upkeep],['costOverride',s.build]].map(([k,v])=>`<td><input type="number" min="0" step=".01" data-asset="${esc(r.id)}" data-field="${k}" value="${rule[k]??''}" placeholder="${v}"><small>${gp(v)}${rule[k]===undefined?' · automatisch':' · aangepast'}</small></td>`).join('')}</tr>`}).join('')}</tbody></table></div><h2>Percelen</h2><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Perceel</th><th>Eigenaar</th><th>Vakken</th></tr></thead><tbody>${(data.map?.plots||[]).filter(p=>financeOwner==='all'||p.ownerId===financeOwner||!p.ownerId).map(p=>`<tr><td>${esc(plotLabel(p))}</td><td><select data-plot-owner="${esc(p.id)}">${ownerOptions(p.ownerId)}</select></td><td>${plotCells(p).length}</td></tr>`).join('')||'<tr><td colspan="3">Nog geen percelen getekend.</td></tr>'}</tbody></table></div><p class="finance-note">Niet toegewezen panden staan in de tabel, maar worden pas na toewijzing bij een inwoner opgeteld. Leegmaken van een aangepast bedrag herstelt de automatische berekening.</p>`;
document.querySelectorAll('[data-plot-finance]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return;const r=f.plotRules[el.dataset.plotFinance]??={};r[el.dataset.field]=el.dataset.field==='name'?el.value.trim():Number(el.value);persist();render()});document.querySelectorAll('[data-asset-owner]').forEach(el=>el.onchange=()=>{data.locaties.find(r=>r.id===el.dataset.assetOwner).ownerId=el.value;persist();render()});document.querySelectorAll('[data-plot-owner]').forEach(el=>el.onchange=()=>{const p=data.map.plots.find(r=>r.id===el.dataset.plotOwner);p.ownerId=el.value;mergeOwnerPlots(p.ownerId);persist();render()});document.querySelectorAll('[data-extra-plots]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return;f.extraPlots[el.dataset.extraPlots]=Number(el.value);persist();render()});document.querySelectorAll('[data-asset]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return;const r=f.assets[el.dataset.asset]??={},k=el.dataset.field;if(el.value===''&&k.endsWith('Override'))delete r[k];else r[k]=['profile','staff'].includes(k)?el.value:Number(el.value);persist();render()});}
function renderFinanceRates(){const f=ensureFinance();$('#financeBody').innerHTML=`<h2>Aanpasbare kosten en opbrengsten</h2><p>Standaarden uit jouw Tarnstead-basisregels. Een wijziging rekent direct door voor panden zonder eigen aangepast bedrag.</p><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Type</th><th>Eenmalige kosten (gp)</th><th>Basisinkomsten / week (gp)</th><th>Onderhoud / week (gp)</th></tr></thead><tbody>${activeProfiles().map(p=>`<tr><td><input data-rate="${p.id}" data-field="name" value="${esc(p.name)}" required maxlength="80"></td>${['cost','income','upkeep'].map(k=>`<td><input type="number" min="0" step=".01" data-rate="${p.id}" data-field="${k}" value="${p[k]}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><h2>Personeel</h2><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Niveau</th><th>Loon / week (gp)</th><th>Opbrengstfactor</th></tr></thead><tbody>${activeStaff().map(p=>`<tr><td><input data-staff="${p.id}" data-field="name" value="${esc(p.name)}" required maxlength="80"></td><td><input type="number" min="0" step=".01" data-staff="${p.id}" data-field="wage" value="${p.wage}"></td><td><input type="number" min="0" step=".05" data-staff="${p.id}" data-field="factor" value="${p.factor}"></td></tr>`).join('')}</tbody></table></div><h2>Grond</h2><div class="finance-ground">${f.plotPrices.map((v,i)=>`<label>${i+1}e plot (gp)<input type="number" min="0" step=".01" data-plot-price="${i}" value="${v}"></label>`).join('')}<label>Vakken per startplot<input id="startPlotCells" type="number" min="1" step="1" value="${f.startPlotCells}"></label></div><p class="finance-note">Profielen worden expliciet gekozen; een grotere getekende footprint verandert de tier niet vanzelf. Een werkplaatsmodule telt ${gp(f.catalog.find(p=>p.id==='workshopModule').cost)} eenmalig en ${gp(f.catalog.find(p=>p.id==='workshopModule').income)} basisopbrengst per week.</p>`;
for(const attr of ['rate','staff'])document.querySelectorAll('[data-'+attr+']').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return;f[attr==='rate'?'catalog':'staff'].find(r=>r.id===el.dataset[attr])[el.dataset.field]=el.dataset.field==='name'?el.value.trim():Number(el.value);persist();render()});document.querySelectorAll('[data-plot-price]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return;f.plotPrices[Number(el.dataset.plotPrice)]=Number(el.value);persist();render()});$('#startPlotCells').onchange=e=>{if(!e.target.checkValidity())return;f.startPlotCells=Number(e.target.value);persist();render()};}
function renderFinanceExpenses(){const f=ensureFinance();$('#financeBody').innerHTML=`<h2>Extra kosten</h2><p>Bijvoorbeeld belasting, reparaties of huur. Weekkosten verminderen de netto-opbrengst; eenmalige kosten staan apart.</p><form id="expenseForm" class="expense-form"><label>Inwoner<select name="ownerId" required>${ownerOptions(financeOwner==='all'?'':financeOwner,'Kies een inwoner')}</select></label><label>Omschrijving<input name="label" required maxlength="100"></label><label>Bedrag (gp)<input type="number" name="amount" min="0" step=".01" required></label><label>Periode<select name="period"><option value="week">Per week</option><option value="once">Eenmalig</option></select></label><button class="primary">+ Kosten toevoegen</button></form><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Inwoner</th><th>Omschrijving</th><th>Bedrag (gp)</th><th>Periode</th><th></th></tr></thead><tbody>${f.expenses.filter(e=>financeOwner==='all'||e.ownerId===financeOwner).map(e=>`<tr><td><select data-expense="${e.id}" data-field="ownerId">${ownerOptions(e.ownerId)}</select></td><td><input data-expense="${e.id}" data-field="label" value="${esc(e.label)}"></td><td><input type="number" min="0" step=".01" data-expense="${e.id}" data-field="amount" value="${e.amount}"></td><td><select data-expense="${e.id}" data-field="period"><option value="week" ${e.period==='week'?'selected':''}>Per week</option><option value="once" ${e.period==='once'?'selected':''}>Eenmalig</option></select></td><td><button data-remove-expense="${e.id}">Verwijderen</button></td></tr>`).join('')}</tbody></table></div>`;
$('#expenseForm').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);f.expenses.push({id:crypto.randomUUID(),ownerId:form.get('ownerId'),label:String(form.get('label')).trim(),amount:Number(form.get('amount')),period:form.get('period')});persist();render()};document.querySelectorAll('[data-expense]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return;f.expenses.find(e=>e.id===el.dataset.expense)[el.dataset.field]=el.dataset.field==='amount'?Number(el.value):el.value;persist();render()});document.querySelectorAll('[data-remove-expense]').forEach(el=>el.onclick=()=>{f.expenses=f.expenses.filter(e=>e.id!==el.dataset.removeExpense);persist();render()});}

function addFinanceSave(){const button=document.createElement('button');button.className='primary';button.textContent='Wijzigingen bewaren';button.id='saveFinanceChanges';$('#financeBody').prepend(button);button.onclick=()=>{const f=ensureFinance(),inputs=[...$('#financeBody').querySelectorAll('input,select')].filter(el=>!el.closest('form')&&!el.disabled);if(inputs.some(el=>!el.checkValidity())){toast('Controleer de bedragen.');return}for(const el of inputs){const d=el.dataset;if(d.rate||d.staff)f[d.rate?'catalog':'staff'].find(r=>r.id===(d.rate||d.staff))[d.field]=d.field==='name'?el.value.trim():Number(el.value);if(d.plotPrice!==undefined)f.plotPrices[Number(d.plotPrice)]=Number(el.value);if(el.id==='startPlotCells')f.startPlotCells=Number(el.value);if(el.id==='ownerFactor')f.ownerFactor=Number(el.value);if(d.extraPlots)f.extraPlots[d.extraPlots]=Number(el.value);if(d.asset){const rule=f.assets[d.asset]??={};if(d.field.endsWith('Override')&&el.value==='')delete rule[d.field];else rule[d.field]=d.field==='ownerWorks'?el.checked:['profile','staff'].includes(d.field)?el.value:Number(el.value)}if(d.assetOwner)data.locaties.find(r=>r.id===d.assetOwner).ownerId=el.value;if(d.plotOwner)data.map.plots.find(r=>r.id===d.plotOwner).ownerId=el.value;if(d.plotFinance)(f.plotRules[d.plotFinance]??={})[d.field]=Number(el.value);if(d.expense)f.expenses.find(e=>e.id===d.expense)[d.field]=d.field==='amount'?Number(el.value):el.value;}persist();render();toast('Bezittingen en bedragen bewaard.')}}
function isWorkshopLocation(r){const p=data.finance?.catalog?.find(p=>p.id===data.finance?.assets?.[r.id]?.profile);return p?p.workshop:r.kind==='Werkplaats'}
function prepareKindControl(type,r){const old=$('#form').elements.kind,label=old.closest('label');label.hidden=type==='tijdlijn';let control;if(type==='locaties'){const f=ensureFinance();control=document.createElement('select');control.name='kind';control.required=true;const existing=f.assets[r.id]?.profile||f.catalog.find(p=>p.name===r.kind)?.id;control.innerHTML=(!existing&&r.kind?`<option value="${esc(r.kind)}">${esc(r.kind)} (bestaand type)</option>`:'')+f.catalog.filter(p=>!p.archived||p.id===existing).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');control.value=existing||r.kind||'tent'}else{control=document.createElement('input');control.name='kind';control.required=type!=='tijdlijn';control.maxLength=100;control.value=r.kind||''}old.replaceWith(control);}
function addRateForms(){const f=ensureFinance(),container=document.createElement('div');container.className='rate-additions';container.innerHTML=`<h2>Nieuw regelprofiel</h2><form id="addRateForm" class="expense-form"><label>Naam<input name="name" required maxlength="80"></label><label>Eenmalig (gp)<input name="cost" type="number" min="0" step=".01" value="0" required></label><label>Inkomsten / week (gp)<input name="income" type="number" min="0" step=".01" value="0" required></label><label>Onderhoud / week (gp)<input name="upkeep" type="number" min="0" step=".01" value="0" required></label><button class="primary">+ Profiel toevoegen</button></form><h2>Nieuw personeelsniveau</h2><form id="addStaffForm" class="expense-form"><label>Naam<input name="name" required maxlength="80"></label><label>Loon / week (gp)<input name="wage" type="number" min="0" step=".01" value="0" required></label><label>Opbrengstfactor<input name="factor" type="number" min="0" step=".01" value="1" required></label><button class="primary">+ Niveau toevoegen</button></form>`;$('#financeBody').append(container);$('#addRateForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);if(!String(d.get('name')).trim())return;f.catalog.push({id:'custom-'+crypto.randomUUID(),name:String(d.get('name')).trim(),cost:Number(d.get('cost')),income:Number(d.get('income')),upkeep:Number(d.get('upkeep')),workshop:true});persist();render();toast('Regelprofiel toegevoegd')};$('#addStaffForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);if(!String(d.get('name')).trim())return;f.staff.push({id:'staff-'+crypto.randomUUID(),name:String(d.get('name')).trim(),wage:Number(d.get('wage')),factor:Number(d.get('factor'))});persist();render();toast('Personeelsniveau toegevoegd')};}
function financeExportTextRaw(format){const residents=data.inwoners.filter(n=>financeOwner==='all'||n.id===financeOwner),summary=residents.map(n=>({n,s:residentFinance(n.id)})),f=ensureFinance(),filename=(data.villageName||'plaats').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-bezittingen';if(format==='json')return {text:JSON.stringify({version:'1.35.0',placeName:data.villageName,finance:f,owners:summary.map(({n,s})=>({id:n.id,name:n.name,...s}))},null,2),filename:filename+'.json',type:'application/json'};if(format==='csv'){const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"',rows=[['Inwoner','Panden','Perceelvakken','Omzet per week (gp)','Kosten per week (gp)','Netto per week (gp)','Waarde bezittingen (gp)'],...summary.map(({n,s})=>[n.name,s.assets.length,s.cells,s.income,s.upkeep,s.net,s.value])];return {text:'\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),filename:filename+'.csv',type:'text/csv;charset=utf-8'}}const md=v=>String(v??'').replace(/\|/g,'\\|').replace(/\r?\n/g,' ');let lines=[`# Kanselarij — ${md(data.villageName)}`,'','Bedragen zijn in gp. Omzet is bruto; weekkosten en eenmalige kosten staan apart.','', '| Inwoner | Panden | Perceelvakken | Omzet / week | Kosten / week | Netto / week | Waarde |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |',...summary.map(({n,s})=>`| ${md(n.name)} | ${s.assets.length} | ${s.cells} | ${gp(s.income)} | ${gp(s.upkeep)} | ${gp(s.net)} | ${gp(s.value)} |`)];for(const {n,s}of summary){lines.push('',`## ${md(n.name)}`,'','### Panden','','| Pand | Profiel | Personeel | Omzet / week | Kosten / week | Waarde |','| --- | --- | --- | ---: | ---: | ---: |',...s.assets.map(r=>{const a=assetFinance(r);return `| ${md(r.name)} | ${md(a.profile.name)} | ${md(a.staff.name)} | ${gp(a.income)} | ${gp(a.upkeep)} | ${gp(a.build)} |`}), '',`Percelen: ${s.plots.length}; totaal ${s.cells} rastervakken. Geen perceelinkomsten of weekkosten.`, '', '### Extra kosten','',...f.expenses.filter(e=>e.ownerId===n.id).map(e=>`- ${md(e.label)}: ${gp(e.amount)} (${e.period==='week'?'per week (inactief)':'eenmalig (inactief)'}).`))}return {text:lines.join('\n')+'\n',filename:filename+'.md',type:'text/markdown;charset=utf-8'}}
$('#cancelFinanceExport').onclick=()=>$('#financeExportEditor').close();$('#financeExportForm').onsubmit=e=>{e.preventDefault();const out=financeExportText($('#financeExportFormat').value);downloadData(out.text,out.filename,out.type);$('#financeExportEditor').close()};

function activeProfiles(){return ensureFinance().catalog.filter(p=>!p.archived)}
function activeStaff(){return ensureFinance().staff.filter(p=>!p.archived)}
function configureSidebar(){const button=document.createElement('button');button.id='sidebarToggle';button.title='Zijbalk in- of uitklappen';button.setAttribute('aria-label',button.title);button.textContent='☰';document.querySelector('aside').prepend(button);let collapsed=false;try{collapsed=localStorage.getItem('fvm-sidebar-collapsed')==='true'}catch{}document.body.classList.toggle('sidebar-collapsed',collapsed);button.setAttribute('aria-expanded',String(!collapsed));document.querySelectorAll('nav button').forEach(b=>b.title=b.textContent.trim());button.onclick=()=>{const value=document.body.classList.toggle('sidebar-collapsed');button.setAttribute('aria-expanded',String(!value));try{localStorage.setItem('fvm-sidebar-collapsed',String(value))}catch{}}}
function splitFinanceAssets(tab){const body=$('#financeBody'),cards=body.querySelector('.cards'),headings=[...body.querySelectorAll('h2')],buildingHeading=headings.find(h=>h.textContent==='Panden en eigenaren'),plotHeading=headings.find(h=>h.textContent==='Percelen');if(!buildingHeading||!plotHeading)return;const nodes=[...body.children],bi=nodes.indexOf(buildingHeading),pi=nodes.indexOf(plotHeading);if(tab==='overview')nodes.forEach(n=>{if(n!==cards)n.remove()});if(tab==='buildings')nodes.forEach((n,i)=>{if(i<bi)n.remove()});if(tab==='plots')nodes.forEach((n,i)=>{if(i<pi)n.remove()});}
function enhanceStaffing(){const f=ensureFinance();document.querySelectorAll('select[data-asset][data-field="staff"]').forEach(select=>{const id=select.dataset.asset,rule=f.assets[id]||{},r=data.locaties.find(r=>r.id===id),summary=assetFinance(r),td=select.closest('td');td.insertAdjacentHTML('beforeend',`<label class="owner-work"><input type="checkbox" data-asset="${esc(id)}" data-field="ownerWorks" ${rule.ownerWorks?'checked':''} ${profileOwnerWorkAllowed(summary.profile)?'':'disabled hidden'}> Eigenaar werkt mee</label>`);});document.querySelectorAll('[data-field="ownerWorks"]').forEach(el=>el.onchange=()=>{(f.assets[el.dataset.asset]??={}).ownerWorks=el.checked;persist();render()});}
function enhanceRates(){const f=ensureFinance(),body=$('#financeBody'),wraps=[...body.querySelectorAll('.finance-table-wrap')];if(wraps.length<2)return;for(const [i,key]of [[0,'catalog'],[1,'staff']]){const table=wraps[i].querySelector('table');table.querySelector('thead tr').insertAdjacentHTML('beforeend','<th>Actie</th>');const profiles=key==='catalog'?activeProfiles():activeStaff();table.querySelectorAll('tbody tr').forEach((tr,index)=>{const profile=profiles[index];if(profile)tr.insertAdjacentHTML('beforeend',`<td><button data-archive-rule="${esc(profile.id)}" data-rule-group="${key}">Verwijderen</button></td>`)});}
body.querySelectorAll('[data-archive-rule]').forEach(b=>b.onclick=()=>{const f=ensureFinance(),item=f[b.dataset.ruleGroup].find(p=>p.id===b.dataset.archiveRule);item.archived=true;persist();render();toast('Regel verwijderd uit de keuzelijst. Bestaande panden behouden hun berekening.')});
const addRate=$('#addRateForm'),addStaff=$('#addStaffForm');if(addRate){const title=addRate.previousElementSibling;wraps[0].after(title,addRate)}if(addStaff){const title=addStaff.previousElementSibling;wraps[1].after(title,addStaff)}body.querySelector('.rate-additions')?.remove();
const ownerControls=document.createElement('div');ownerControls.className='finance-ground';ownerControls.innerHTML=`<label>Opbrengstfactor meewerkende eigenaar<input id="ownerFactor" type="number" min="0" step=".05" value="${f.ownerFactor}"></label><p class="finance-note">Bij meewerken wordt de basisopbrengst vermenigvuldigd met deze factor én de personeelsfactor. Zonder personeel kan de eigenaar zelfstandig werken; de eigenaar ontvangt geen personeelsloon.</p>`;wraps[1].after(ownerControls);$('#ownerFactor').onchange=e=>{if(!e.target.checkValidity())return;f.ownerFactor=Number(e.target.value);persist();render()};}
function payoutKey(week,id){return paymentScope()+week+':'+id}
function payoutAmount(n){return Math.max(0,residentFinance(n.id).net)}
function preparePayoutWeek(week){if(!Number.isInteger(week)||week<1||week>timelinePaymentWeek())return;const f=ensureFinance();f.payouts??={};for(const n of data.inwoners){const key=payoutKey(week,n.id);if(!f.payoutRecipients[n.id]||!withDatedState(paymentPeriodEndDay(week),()=>data.inwoners.some(r=>r.id===n.id)))continue;let p=f.payouts[key];if(p?.paid||p?.cancelled)continue;const snapshot=withDatedState(paymentPeriodEndDay(week),()=>{const s=residentFinance(n.id),lodgingRevenue=s.assets.reduce((a,r)=>a+assetFinance(r).lodging,0),wages=s.assets.reduce((a,r)=>a+assetFinance(r).staff.wage,0)+independentPlayerWages(n.id),actualLodging=periodLodgingCost(n.id,week);return {net:s.net-lodgingRevenue+wages+s.lodging-actualLodging,lodging:actualLodging,innOwner:lodgingInn()?.ownerId||''}});if(Math.abs(snapshot.net)<0.005){if(p&&!p.paid)delete f.payouts[key];continue}if(!p)p=f.payouts[key]={paid:false,campaignDay:currentEffectiveDay()};p.amount=Math.abs(snapshot.net);p.direction=snapshot.net<0?'inbound':'outbound';p.lodgingDue=snapshot.lodging;p.innOwnerId=snapshot.innOwner;p.bankModel=true}}

function outstandingPayouts(residents,exceptWeek){const ids=new Set(residents.map(n=>n.id));return Object.entries(ensureFinance().payouts||{}).flatMap(([key,p])=>{if(!key.startsWith(paymentScope()))return [];const [week,...rest]=key.slice(paymentScope().length).split(':'),id=rest.join(':');return !p.paid&&ids.has(id)&&Number(week)<=timelinePaymentWeek()&&Number(week)!==exceptWeek?[{week:Number(week),id,...p}]:[]}).sort((a,b)=>a.week-b.week)}
function renderPayouts(residents){if(timelinePaymentWeek()<1){$('#financeBody').innerHTML='<h2>Betalingen</h2><p>Er is nog geen volledige campagneweek verstreken.</p>';return}const f=ensureFinance();f.payoutWeek=Math.min(Math.max(1,Number(f.payoutWeek)||Math.max(1,timelinePaymentWeek())),Math.max(1,timelinePaymentWeek()));const week=Math.max(1,Math.floor(f.payoutWeek||Math.max(1,timelinePaymentWeek())));f.payouts??={};preparePayoutWeek(week);persist();const open=outstandingPayouts(residents,week),payment=n=>f.payouts[payoutKey(week,n.id)];$('#financeBody').innerHTML=`<h2>Betalingen</h2><div class="payout-toolbar"><label>Campagneweek<input id="payoutWeek" type="number" min="1" max="${Math.max(1,timelinePaymentWeek())}" step="1" value="${week}"></label><button id="showPayoutWeek">Week tonen</button><button id="selectAllPayouts">Alles selecteren</button><button id="clearPayoutSelection">Selectie wissen</button><button id="payoutExport">↓ Weekoverzicht (.md)</button></div><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Ontvanger</th><th>Inwoner</th><th>Netto / week</th><th>Uit te betalen</th><th>Status</th><th></th></tr></thead><tbody>${residents.map(n=>{const p=payment(n),include=f.payoutRecipients[n.id]===true;return `<tr><td><input type="checkbox" data-payout-recipient="${esc(n.id)}" ${include?'checked':''}></td><td>${esc(n.name)}</td><td>${gp(residentFinance(n.id).net)}</td><td>${gp(p?.amount||0)}</td><td>${p?.paid?'Betaald':p?'Openstaand':'Niet geselecteerd'}</td><td><button ${!p?'disabled':''} data-pay-resident="${esc(n.id)}">${p?.paid?'Heropenen':'Markeer betaald'}</button></td></tr>`}).join('')}</tbody></table></div><p><b>Openstaand deze week: ${gp(residents.reduce((sum,n)=>sum+(payment(n)?.paid?0:payment(n)?.amount||0),0))}</b></p><h2>Openstaand uit andere weken</h2><p class="finance-note">Alleen klaargezette weken worden geregistreerd. Selectie wissen annuleert geen bestaande betaling.</p>${open.length?`<div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Week</th><th>Inwoner</th><th>Bedrag</th><th></th></tr></thead><tbody>${open.map(p=>`<tr><td>${p.week}</td><td>${esc(data.inwoners.find(n=>n.id===p.id)?.name||p.id)}</td><td>${gp(p.amount)}</td><td><button data-open-payout-week="${p.week}">Week openen</button></td></tr>`).join('')}</tbody></table></div><p><b>Totaal andere weken: ${gp(open.reduce((a,p)=>a+p.amount,0))}</b></p>`:'<p>Geen openstaande betalingen uit andere klaargezette weken.</p>'}`;
const show=()=>{if(!$('#payoutWeek').checkValidity())return;f.payoutWeek=Number($('#payoutWeek').value);persist();render()};$('#showPayoutWeek').onclick=show;$('#payoutWeek').onchange=show;$('#selectAllPayouts').onclick=()=>{residents.forEach(n=>f.payoutRecipients[n.id]=true);preparePayoutWeek(week);persist();render()};$('#clearPayoutSelection').onclick=()=>{residents.forEach(n=>f.payoutRecipients[n.id]=false);persist();render()};document.querySelectorAll('[data-payout-recipient]').forEach(el=>el.onchange=()=>{f.payoutRecipients[el.dataset.payoutRecipient]=el.checked;preparePayoutWeek(week);persist();render()});document.querySelectorAll('[data-open-payout-week]').forEach(b=>b.onclick=()=>{f.payoutWeek=Number(b.dataset.openPayoutWeek);persist();render()});document.querySelectorAll('[data-pay-resident]').forEach(b=>b.onclick=()=>{const p=f.payouts[payoutKey(week,b.dataset.payResident)];p.paid=!p.paid;if(p.paid)p.paidDay=data.day;persist();render()});$('#payoutExport').onclick=()=>{const md=v=>String(v).replace(/\|/g,'\\|').replace(/\r?\n/g,' '),rows=residents.filter(payment).map(n=>{const p=payment(n);return `| ${md(n.name)} | ${gp(p.amount)} | ${p.paid?'Betaald':'Openstaand'} |`});downloadData(`# Betalingen — ${md(data.villageName)} — week ${week}\n\n| Inwoner | Bedrag | Status |\n| --- | ---: | --- |\n${rows.join('\n')}\n`,'uitbetalingen-week-'+week+'.md','text/markdown;charset=utf-8')};}

function normalizeOwnerLevel(f){for(const tier of f.staff.filter(s=>s.name.trim().toLowerCase()==='eigenaar')){tier.archived=true;tier.ownerLevel=true;for(const rule of Object.values(f.assets)){if(rule.staff===tier.id){rule.legacyOwnerTier=tier.id;rule.ownerWorks=true;if(Number(tier.factor)!==2)rule.ownerFactorOverride=Number(tier.factor);else delete rule.ownerFactorOverride;rule.staff='none';}}}}
const harptosMonths=['Hammer','Alturiak','Ches','Tarsakh','Mirtul','Kythorn','Flamerule','Eleasis','Eleint','Marpenoth','Uktar','Nightal'];
function calendarConfig(){return data.calendar??={system:'harptos',harptosStart:{year:1492,month:'Hammer',day:1},gregorianStart:'2026-01-01'}}
function harptosSegments(year){return harptosMonths.flatMap((name,i)=>[{name,length:30},...(i===0?[{name:'Midwinter',length:1}]:i===3?[{name:'Greengrass',length:1}]:i===6?[{name:'Midsummer',length:1},...(year%4===0?[{name:'Shieldmeet',length:1}]:[])]:i===8?[{name:'Highharvestide',length:1}]:i===10?[{name:'Feast of the Moon',length:1}]:[])])}
function harptosOrdinal(date){const y=Number(date.year),segments=harptosSegments(y),index=segments.findIndex(s=>s.name===date.month);if(!Number.isInteger(y)||y<1||y>9999||index<0||!Number.isInteger(Number(date.day))||date.day<1||date.day>segments[index].length)throw Error('Ongeldige Harptos-datum');return (y-1)*365+Math.floor((y-1)/4)+segments.slice(0,index).reduce((a,s)=>a+s.length,0)+Number(date.day)-1}
function harptosDate(ordinal){let year=Math.max(1,Math.floor(ordinal/366)+1);while(year*365+Math.floor(year/4)<=ordinal)year++;let rest=ordinal-((year-1)*365+Math.floor((year-1)/4));for(const s of harptosSegments(year)){if(rest<s.length)return {year,month:s.name,day:rest+1};rest-=s.length}}
function campaignDate(day){const c=calendarConfig();if(c.system==='gregorian'){const d=new Date(c.gregorianStart+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+day-1);return d.toISOString().slice(0,10)}return harptosDate(harptosOrdinal(c.harptosStart)+day-1)}
function calendarLabel(day){const d=campaignDate(day);return typeof d==='string'?new Date(d+'T00:00:00Z').toLocaleDateString('nl-NL',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}):`${harptosMonths.includes(d.month)?d.day+' ':''}${d.month}, ${d.year} DR`}

function prepareEventCalendar(day){const field=$('#form').elements.day,c=calendarConfig();field.closest('label').hidden=true;$('#extra').insertAdjacentHTML('afterbegin',dateFields('eventCalendar',campaignDate(day),c.system)+`<p class="finance-note">Dag ${day} van de campagne · ${c.system==='harptos'?'Harptos':'Gewone kalender'}</p>`);bindDateFields('eventCalendar');for(const e of document.querySelectorAll('[id^="eventCalendar"]'))e.addEventListener('change',()=>{try{const date=readDateFields('eventCalendar',c.system),n=c.system==='gregorian'?Math.round((Date.parse(date)-Date.parse(c.gregorianStart))/86400000)+1:harptosOrdinal(date)-harptosOrdinal(c.harptosStart)+1;field.value=n;const input=$('#eventCalendarDate')||$('#eventCalendarDay');input.setCustomValidity(n<1?'Kies een datum op of na de start van de campagne.':'')}catch{}})}
function syncEventCalendar(){try{const c=calendarConfig(),date=readDateFields('eventCalendar',c.system),day=c.system==='gregorian'?Math.round((Date.parse(date)-Date.parse(c.gregorianStart))/86400000)+1:harptosOrdinal(date)-harptosOrdinal(c.harptosStart)+1;if(day<1||!Number.isInteger(day))throw Error();$('#form').elements.day.value=day;return true}catch{toast('Kies een datum op of na de start van de campagne.');return false}}
function enhanceCalendar(){const population=$('#stats .stat:nth-child(2)');if(population&&view!=='finance')population.title=list('inwoners').length+' geregistreerde inwoners + '+hiredStaffTotal()+' ingehuurde medewerkers';if(view==='finance')return;const stat=$('#stats .stat:last-child b');if(stat)stat.textContent=calendarLabel(latestTimelineDay());if(view!=='tijdlijn')return;document.querySelectorAll('.timeline .card').forEach(card=>{const r=data.tijdlijn.find(e=>e.id===card.dataset.id);if(r)card.querySelector('.tag').textContent=calendarLabel(r.day)+' · '+r.kind+(r.hidden?' · DM':'')});if(player)return;const btn=document.createElement('button');btn.textContent='Kalender instellen';btn.onclick=openCalendarSettings;$('.toolbar').append(btn)}
function openCalendarSettings(){let dialog=$('#calendarEditor');if(!dialog){dialog=document.createElement('dialog');dialog.id='calendarEditor';document.body.append(dialog)}const c=calendarConfig();dialog.innerHTML=`<form id="calendarForm"><span class="tag">CAMPAGNEKALENDER</span><h2>Kalender instellen</h2><label>Kalender<select id="calendarSystem"><option value="harptos" ${c.system==='harptos'?'selected':''}>Harptos (Forgotten Realms)</option><option value="gregorian" ${c.system==='gregorian'?'selected':''}>Gewone kalender</option></select></label><p>Startdatum: deze datum hoort bij campagnedag 1. Gebeurtenissen houden hun campagnedag.</p><div id="calendarStartFields"></div><div class="dialog-actions"><button type="button" id="calendarCancel">Annuleren</button><button class="primary">Bewaren</button></div></form>`;const fields=()=>{const system=$('#calendarSystem').value;$('#calendarStartFields').innerHTML=dateFields('startCalendar',system==='harptos'?c.harptosStart||{year:1492,month:'Hammer',day:1}:c.gregorianStart||'2026-01-01',system);bindDateFields('startCalendar')};fields();$('#calendarSystem').onchange=fields;$('#calendarCancel').onclick=()=>dialog.close();$('#calendarForm').onsubmit=e=>{e.preventDefault();try{const system=$('#calendarSystem').value,date=readDateFields('startCalendar',system);c.system=system;if(system==='harptos')c.harptosStart=date;else c.gregorianStart=date;persist();dialog.close();render()}catch{toast('Controleer de startdatum.')}};dialog.showModal()}

function hiredStaffTotal(){return list('locaties').reduce((sum,r)=>{const a=assetFinance(r);return sum+(a.profile.workshop&&a.staff.id!=='none'&&!a.staff.ownerLevel&&!ensureFinance().assets[r.id]?.staffResidentId?1:0)},0)}
function populationTotal(){return list('inwoners').length+hiredStaffTotal()}
function latestTimelineDay(){const days=list('tijdlijn').map(r=>Number(r.day)).filter(Number.isFinite);return days.length?Math.max(...days):data.day}
function residentWealth(n){const s=residentFinance(n.id),bank=Number(n.bankGp||0),cash=0;return {...s,bank,cash,wealth:s.value+bank}}

