function moveRateRow(group,id,direction){const f=ensureFinance(),rows=f[group],active=rows.filter(r=>!r.archived),index=active.findIndex(r=>r.id===id),other=active[index+direction];if(!other)return false;const a=rows.findIndex(r=>r.id===id),b=rows.indexOf(other);[rows[a],rows[b]]=[rows[b],rows[a]];return true}
function enhanceRateOrder(){for(const [group,selector]of [['catalog','[data-rate]'],['staff','[data-staff]']]){const rows=[...$('#financeBody').querySelectorAll('tbody tr')].filter(tr=>tr.querySelector(selector)),active=ensureFinance()[group].filter(r=>!r.archived);rows.forEach((tr,i)=>{const id=tr.querySelector(selector).dataset[group==='catalog'?'rate':'staff'];tr.lastElementChild.insertAdjacentHTML('afterbegin',`<span class="rate-order"><button type="button" data-move-rule="${esc(id)}" data-group="${group}" data-direction="-1" aria-label="${esc(active[i]?.name)} omhoog" ${i===0?'disabled':''}>↑</button><button type="button" data-move-rule="${esc(id)}" data-group="${group}" data-direction="1" aria-label="${esc(active[i]?.name)} omlaag" ${i===rows.length-1?'disabled':''}>↓</button></span>`)})}document.querySelectorAll('[data-move-rule]').forEach(b=>b.onclick=()=>{const inputs=[...$('#financeBody').querySelectorAll('[data-rate],[data-staff]')];if(inputs.some(e=>!e.checkValidity())){toast('Controleer eerst de ingevoerde tarieven.');return}const f=ensureFinance();for(const el of inputs){const d=el.dataset;f[d.rate?'catalog':'staff'].find(r=>r.id===(d.rate||d.staff))[d.field]=d.field==='name'?el.value.trim():Number(el.value)}moveRateRow(b.dataset.group,b.dataset.moveRule,Number(b.dataset.direction));persist();render()})}
function financeBreakdowns(){const residents=data.inwoners.filter(n=>financeOwner==='all'||n.id===financeOwner),assets=data.locaties.filter(r=>financeOwner==='all'||r.ownerId===financeOwner),lines=assets.map(r=>{const a=assetFinance(r),rule=ensureFinance().assets[r.id]||{};return {id:r.id,ownerId:r.ownerId,name:r.name,a,formula:rule.incomeOverride!==undefined?'handmatig ingesteld':a.profile.workshop?`basis ${gp(a.profile.income)} + ${a.modules} uitbreidingen; eigenaar ×${rule.ownerWorks&&profileOwnerWorkAllowed(a.profile)?Number(rule.ownerFactorOverride??ensureFinance().ownerFactor):1}; personeel ×${rule.ownerWorks&&a.staff.id==='none'?1:a.staff.factor}`:'basisopbrengst profiel'}}),owned=lines.filter(l=>residents.some(n=>n.id===l.ownerId));const values=residents.map(n=>residentFinance(n.id));return [`Netto = omzet − kosten (inclusief overnachtingen)\n${residents.map((n,i)=>`${n.name}: ${gp(values[i].income)} − ${gp(values[i].upkeep)} = ${gp(values[i].net)}`).join('\n')}`,`Weekkosten per pand (onderhoud + personeel)\n${residents.filter(needsLodging).map(n=>`${n.name}: overnachtingen ${lodgingName()} ${gp(lodgingRate()*paymentPeriodDays())}`).join('\n')}\n${owned.map(l=>`${l.name}: ${gp(l.a.upkeep)}${ensureFinance().assets[l.id]?.upkeepOverride!==undefined?' (handmatig)':` (onderhoud ${gp(l.a.profile.upkeep)} + loon ${gp(l.a.profile.workshop?l.a.staff.wage:0)})`}`).join('\n')}`,`Omzet per pand\n${owned.map(l=>`${l.name}: ${gp(l.a.income)} — ${l.formula}${l.a.lodging?` + ${gp(l.a.lodging)} overnachtingen`:""}`).join('\n')}`,`Waarde = panden + grond\n${lines.map(l=>`${l.name}: ${gp(l.a.build)}`).join('\n')}\n${residents.map(n=>`${n.name} — grond: ${gp(residentFinance(n.id).plotCost)}`).join('\n')}\nOok het eerste plot telt mee tegen het eerste grondtarief. Bankgeld telt hier niet mee.`]}
function enhanceFinanceDetails(){if(financeTab==='registry')return;const details=financeBreakdowns();document.querySelectorAll('#stats .stat').forEach((stat,i)=>{stat.removeAttribute('title');stat.tabIndex=0;stat.setAttribute('aria-label',stat.textContent+' '+details[i]);const tip=document.createElement('div');tip.className='stat-breakdown';tip.textContent=details[i];tip.setAttribute('role','tooltip');stat.append(tip)})}

let financeOverviewSort='value',financeOverviewDirection=-1,financeBuildingSort=0,financeBuildingDirection=1;
function bindFinanceAutosave(){const body=$('#financeBody');body.insertAdjacentHTML('afterbegin','<p class="finance-note">Wijzigingen worden automatisch opgeslagen.</p>');for(const el of body.querySelectorAll('input,select')){if(el.closest('form')||el.disabled)continue;const change=el.onchange;if(!change)continue;el.addEventListener('input',()=>{if(el.type==='checkbox'||el.tagName==='SELECT'||!el.checkValidity()||el.type==='number'&&el.value===''&&!el.dataset.field?.endsWith('Override'))return;const f=ensureFinance(),d=el.dataset;if(d.rate||d.staff)f[d.rate?'catalog':'staff'].find(r=>r.id===(d.rate||d.staff))[d.field]=d.field==='name'?el.value.trim():Number(el.value);if(d.asset){const rule=f.assets[d.asset]??={};if(d.field.endsWith('Override')&&el.value==='')delete rule[d.field];else rule[d.field]=Number(el.value)}if(d.plotPrice!==undefined)f.plotPrices[Number(d.plotPrice)]=Number(el.value);if(el.id==='startPlotCells')f.startPlotCells=Number(el.value);if(el.id==='ownerFactor')f.ownerFactor=Number(el.value);persist()})}}
function compareFinanceValues(a,b){return typeof a==='number'&&typeof b==='number'?a-b:String(a).localeCompare(String(b),'nl',{numeric:true,sensitivity:'base'})}
function enhanceFinanceSorting(){if(financeTab==='overview'){const cards=$('#financeBody .cards');if(!cards)return;const controls=document.createElement('div');controls.className='finance-toolbar';controls.innerHTML=`<label>Sorteren op<select id="financeSort">${[['value','Waarde'],['name','Voornaam'],['cells','Perceelvakken']].map(([v,l])=>`<option value="${v}" ${v===financeOverviewSort?'selected':''}>${l}</option>`).join('')}</select></label><label>Volgorde<select id="financeSortDirection"><option value="1" ${financeOverviewDirection===1?'selected':''}>Laag naar hoog / A–Z</option><option value="-1" ${financeOverviewDirection===-1?'selected':''}>Hoog naar laag / Z–A</option></select></label>`;cards.before(controls);const residents=data.inwoners.filter(n=>financeOwner==='all'||n.id===financeOwner),nodes=[...cards.children].map((node,i)=>({node,n:residents[i]}));nodes.sort((a,b)=>financeOverviewDirection*compareFinanceValues(financeOverviewSort==='name'?a.n.name.trim().split(/\s+/)[0]:residentFinance(a.n.id)[financeOverviewSort],financeOverviewSort==='name'?b.n.name.trim().split(/\s+/)[0]:residentFinance(b.n.id)[financeOverviewSort]));nodes.forEach(r=>cards.append(r.node));$('#financeSort').onchange=e=>{financeOverviewSort=e.target.value;render()};$('#financeSortDirection').onchange=e=>{financeOverviewDirection=Number(e.target.value);render()}}if(financeTab==='buildings'){const table=$('#financeBody table'),rows=[...table.tBodies[0].rows];const value=(row,index)=>{const td=row.cells[index],select=td.querySelector('select'),input=td.querySelector('input');if(select)return select.selectedOptions[0]?.textContent||'';if(input)return input.type==='number'?Number(input.value||input.placeholder||0):input.value;return td.textContent};rows.sort((a,b)=>financeBuildingDirection*compareFinanceValues(value(a,financeBuildingSort),value(b,financeBuildingSort)));rows.forEach(r=>table.tBodies[0].append(r));[...table.tHead.rows[0].cells].forEach((th,index)=>{const text=th.textContent;th.innerHTML=`<button class="column-sort" type="button">${esc(text)} ${index===financeBuildingSort?(financeBuildingDirection===1?'↑':'↓'):'↕'}</button>`;th.setAttribute('aria-sort',index===financeBuildingSort?(financeBuildingDirection===1?'ascending':'descending'):'none');th.querySelector('button').onclick=()=>{if(financeBuildingSort===index)financeBuildingDirection*=-1;else{financeBuildingSort=index;financeBuildingDirection=1}render()}})}}

