function renderResidentRanking(){if(view!=='inwoners')return;const cards=$('.resident-cards');if(!cards)return;cards.classList.add('resident-ranking');[...cards.children].forEach((card,i)=>{const n=data.inwoners.find(n=>n.id===card.dataset.id);if(!n)return;const s=residentWealth(n),home=data.locaties.find(l=>l.id===n.location),work=data.locaties.find(l=>l.id===n.workplace);card.innerHTML=`${!player?`<b class="resident-rank">${i+1}</b>`:''}<div class="rank-person">${n.portrait?`<img class="resident-portrait" src="${esc(n.portrait)}" alt="${esc(n.name)}">`:''}<span class="tag">${esc(n.kind)}</span><h2>${esc(n.name)}</h2><p>${home?'Woonplek: '+esc(home.name):n.npc?'Geen slaapplek toegewezen':'Overnacht in '+lodgingName()+' · '+gp(lodgingRate())+' / nacht'}${work?'<br>Werkplek: '+esc(work.name):n.workplace==='__travel__'?'<br>Werkplek: Op reis':''}</p>${n.description?`<p>${esc(n.description)}</p>`:''}${secret(n)}</div>${!player?`<div class="rank-wealth"><b>${gp(s.wealth)}</b><p>Panden ${gp(s.value-s.plotCost)} · grond ${gp(s.plotCost)}<br>Bank ${gp(s.bank)}</p></div><div class="rank-property"><b>Bezittingen</b><p>${s.assets.map(l=>esc(l.name)).join(', ')||'Geen panden'}<br>${s.plots.length} percelen · ${s.cells} vakjes</p><b>${gp(s.net)} netto / week</b><p>${gp(s.income)} omzet − ${gp(s.upkeep)} kosten${s.lodging?`<br>Inclusief ${gp(s.lodging)} overnachtingen`:""}</p></div>`:''}`})}

function lodgingRate(){return Number(ensureFinance().lodgingNightly??1)}
function addLodgingRate(){const box=document.createElement('div');box.innerHTML=`<h2>Overnachtingen</h2><label>${esc(lodgingName())} — tarief per nacht (gp)<input id="lodgingNightly" type="number" min="0" step=".01" value="${lodgingRate()}"></label><p class="finance-note">Zeven nachten per campagneweek. Kosten voor inwoners zonder slaapplek; inkomsten voor de eigenaar. Reeds klaargezette betalingen houden hun oorspronkelijke bedrag.</p>`;$('#financeBody').append(box);const input=$('#lodgingNightly');input.oninput=()=>{if(input.value!==''&&input.checkValidity()){ensureFinance().lodgingNightly=Number(input.value);persist()}};input.onchange=()=>{if(input.value!==''&&input.checkValidity()){ensureFinance().lodgingNightly=Number(input.value);persist();render()}}}
function paymentStatus(p){return p.received?'Ontvangen':p.paid?'Betaald, ontvangst onbevestigd':'Openstaand'}
function addReceiptControls(){if(financeTab!=='payouts'||timelinePaymentWeek()<1)return;const f=ensureFinance(),week=Math.max(1,Math.floor(f.payoutWeek||Math.max(1,timelinePaymentWeek())));document.querySelectorAll('[data-pay-resident]').forEach(button=>{const id=button.dataset.payResident,p=f.payouts[payoutKey(week,id)],net=residentFinance(id).net;if(p&&!p.direction&&!p.paid&&p.amount===0&&net<0){p.amount=Math.abs(net);p.direction='inbound';persist()}const inbound=p?.direction==='inbound',row=button.closest('tr');row.cells[3].textContent=gp(p?.amount||0)+(inbound?' te ontvangen':'');row.cells[4].textContent=p?paymentStatus(p):'Niet geselecteerd';if(inbound){button.textContent=p.received?'Ontvangst heropenen':'Markeer ontvangen';button.onclick=()=>{p.received=!p.received;p.paid=p.received;if(p.received)p.receivedDay=data.day;persist();render()};return}const received=document.createElement('button');received.textContent=p?.received?'Ontvangst heropenen':'Markeer ontvangen';received.disabled=!p?.paid;received.onclick=()=>{p.received=!p.received;if(p.received)p.receivedDay=data.day;else delete p.receivedDay;persist();render()};button.after(received);button.addEventListener('click',()=>{if(p&&!p.paid){p.received=false;delete p.receivedDay;persist();render()}})})}

function residentLedger(id){const f=ensureFinance();return [...Object.entries(f.salaryPayments||{}).filter(([,p])=>!p.cancelled&&(p.residentId===id||p.employerId===id)&&(p.scope||'')===paymentScope()&&p.week<=timelinePaymentWeek()).map(([key,p])=>({...p,sourceKind:'salary',sourceKey:key,direction:p.residentId===id?'ontvangen':'gedaan',status:p.ownerCashApplied?'Betaald door eigenaar':'Openstaand'})),...Object.entries(f.payouts||{}).filter(([key,p])=>!p.cancelled&&Number(p.amount)>0&&key.startsWith(paymentScope())&&key.slice(paymentScope().length).split(':').slice(1).join(':')===id).map(([key,p])=>({...p,sourceKind:'payout',sourceKey:key,label:payoutDescription(id,p),week:Number(key.slice(paymentScope().length).split(':')[0]),direction:p.direction==='inbound'?'gedaan':'ontvangen',status:paymentStatus(p)})),...(f.transactions||[]).filter(t=>t.residentId===id||t.toResidentId===id).map(t=>({...t,sourceKind:'transaction',sourceKey:t.id,direction:t.toResidentId===id?'ontvangen':t.direction,status:'Geregistreerd'}))].sort((a,b)=>a.week-b.week)}

function residentReportRaw(n){const s=residentWealth(n),md=v=>String(v??'').replace(/\|/g,'\\|').replace(/[\r\n]/g,' '),home=data.locaties.find(l=>l.id===n.location),work=data.locaties.find(l=>l.id===n.workplace);return [`# ${md(n.name)} — ${md(data.villageName)}`,'',`Woonplek: ${md(home?.name||(n.npc?'Geen slaapplek toegewezen':lodgingName()+' (automatisch verblijf)'))}`,`Werkplek: ${md(work?.name||(n.workplace==='__travel__'?'Op reis':'Geen'))}`,civilMarriageText(n.id),...residentCivilRecords(n.id).map(r=>'Akte: '+md(r.number+' · '+r.title+' · '+r.date.label+(r.status==='withdrawn'?' · Ingetrokken':''))),'',`Rijkdom: ${gp(s.wealth)}. Bank: ${gp(s.bank)}.`,`Week: ${gp(s.income)} omzet − ${gp(s.upkeep)} kosten = ${gp(s.net)} netto.`,`Overnachtingen: ${gp(s.lodging)} per week.`,'','## Eigendom','','| Pand | Waarde | Omzet / week | Kosten / week |','| --- | ---: | ---: | ---: |',...s.assets.map(r=>{const a=assetFinance(r);return `| ${md(r.name)} | ${gp(a.build)} | ${gp(a.income)} | ${gp(a.upkeep)} |`}), '',`Grond: ${s.cells} vakjes, ${s.plots.length} ${s.plots.length===1?'perceel':'percelen'}, ${gp(s.plotCost)} waarde.`,...s.plots.map(p=>`- ${md(plotLabel(p))}: ${plotCells(p).length} vakjes.`),'','## Betalingen','','Alleen geregistreerde betalingen; verwachte weekbedragen zijn geen betaalhistorie. Bank- en kasmutaties worden bijgehouden in het kasboek.','','| Week | Omschrijving | Soort voor inwoner | Bedrag | Status |','| ---: | --- | --- | ---: | --- |',...residentLedger(n.id).map(t=>`| ${t.week} | ${md(t.label)} | ${md(t.direction)} | ${gp(t.amount)} | ${md(t.status)} |`)].join('\n')+'\n'}
function addResidentReports(){if(financeTab!=='overview')return;const residents=data.inwoners.filter(n=>financeOwner==='all'||n.id===financeOwner);document.querySelectorAll('.finance-resident').forEach(card=>{const n=residents.find(n=>card.dataset.residentId===n.id);if(!n)return;const button=document.createElement('button');button.textContent='Persoonsoverzicht';button.onclick=()=>openResidentReport(n);card.append(button)})}
