function locationWorkers(r){const f=ensureFinance(),a=assetFinance(r),rule=f.assets[r.id]||{},people=list('inwoners').filter(n=>n.workplace===r.id).map(n=>n.name);if(rule.ownerWorks&&profileOwnerWorkAllowed(a.profile)){const owner=list('inwoners').find(n=>n.id===r.ownerId);if(owner&&!people.includes(owner.name))people.push(owner.name+' (eigenaar)')}if(a.profile.workshop&&a.staff.id!=='none'&&!a.staff.ownerLevel&&!rule.staffResidentId)people.push(a.staff.name+' (naam nog niet gekoppeld)');return people}
function enhanceLocationWorkers(){if(view!=='locaties')return;document.querySelectorAll('#content .card').forEach(card=>{const r=data.locaties.find(l=>l.id===card.dataset.id);if(!r)return;const workers=locationWorkers(r);card.insertAdjacentHTML('beforeend',`<p class="location-workers"><b>Medewerkers</b><br>${workers.length?workers.map(esc).join('<br>'):'Geen medewerkers gekoppeld'}</p>`)})}
function currentTownMetrics(){const residents=data.inwoners.map(n=>residentFinance(n.id)),income=residents.reduce((a,r)=>a+r.income,0),cost=residents.reduce((a,r)=>a+r.upkeep,0);return {day:latestTimelineDay(),population:data.inwoners.length+data.locaties.reduce((a,r)=>{const s=assetFinance(r);return a+(s.staff.id!=='none'&&!s.staff.ownerLevel&&s.profile.workshop&&!ensureFinance().assets[r.id]?.staffResidentId?1:0)},0),value:data.locaties.reduce((a,r)=>a+assetFinance(r).build,0)+residents.reduce((a,r)=>a+r.plotCost,0),income,profit:income-cost,cost}}
function recordTownMetrics(){if(player)return;const point=currentTownMetrics(),history=data.history??=[];const index=history.findIndex(p=>p.day===point.day);if(index<0)history.push(point);else history[index]=point;history.sort((a,b)=>a.day-b.day)}
function townHistoryChart(history,key,label,unit){const width=520,height=180,left=58,right=20,top=20,bottom=35,values=history.map(p=>Number(p[key]||0)),low=Math.min(0,...values),high=Math.max(1,...values),range=high-low,minDay=Math.min(...history.map(p=>p.day)),maxDay=Math.max(...history.map(p=>p.day)),x=day=>left+(day-minDay)/(maxDay-minDay||1)*(width-left-right),y=value=>top+(high-value)/range*(height-top-bottom),format=v=>unit==='gp'?gp(v):String(v);return `<svg viewBox="0 0 ${width} ${height}" role="group" aria-label="${esc(label)} over campagnedagen"><path d="M${left} ${top}V${height-bottom}H${width-right}" fill="none" stroke="#c8cabc"/><text x="${left-7}" y="${top+4}" text-anchor="end">${esc(format(high))}</text><text x="${left-7}" y="${height-bottom}" text-anchor="end">${esc(format(low))}</text><polyline points="${history.map(p=>`${x(p.day)},${y(p[key])}`).join(' ')}" fill="none" stroke="#547456" stroke-width="3"/>${history.map(p=>`<circle cx="${x(p.day)}" cy="${y(p[key])}" r="6" fill="#ad8346" tabindex="0" role="button" aria-label="${esc(label)} op ${esc(calendarLabel(p.day))}: ${esc(format(p[key]))}. Bekijk wijzigingen" data-history-metric="${esc(key)}" data-history-day="${p.day}"><title>${esc(calendarLabel(p.day))} · ${esc(p.eventNames||'')}: ${esc(format(p[key]))}</title></circle>`).join('')}<text x="${left}" y="${height-8}">${esc(calendarLabel(minDay))}</text>${minDay!==maxDay?`<text x="${width-right}" y="${height-8}" text-anchor="end">${esc(calendarLabel(maxDay))}</text>`:""}</svg>`}
function renderTownHistory(){let section=$('#townHistory');section?.remove();if(view!=='finance'||financeTab!=='financialHistory'||player)return;const history=timelineTownMetrics();section=document.createElement('section');section.id='townHistory';section.innerHTML=`<div class="history-title"><h2>Ontwikkeling van ${esc(data.villageName)}</h2><button id="toggleTownHistory" aria-expanded="true">Grafieken verbergen</button></div><div class="town-charts">${[['population','Inwoners',''],['value','Waarde','gp'],['income','Omzet / '+(calendarConfig().system==='harptos'?'tenday':'week'),'gp'],['profit','Winst / '+(calendarConfig().system==='harptos'?'tenday':'week'),'gp'],['cost','Kosten / '+(calendarConfig().system==='harptos'?'tenday':'week'),'gp']].map(([key,label,unit])=>`<article class="interactive-town-chart" tabindex="0" role="button" aria-label="${esc(label)}: bekijk wijzigingen" data-chart-metric="${key}"><h3>${label}</h3>${townHistoryChart(history,key,label,unit)}<span class="chart-detail-hint">Bekijk wijzigingen ↗</span></article>`).join('')}</div>`;$('#financeBody').prepend(section);bindTownHistoryDetails(section);$('#toggleTownHistory').onclick=e=>{const charts=section.querySelector('.town-charts');charts.hidden=!charts.hidden;e.target.textContent=charts.hidden?'Grafieken tonen':'Grafieken verbergen';e.target.setAttribute('aria-expanded',String(!charts.hidden))}}

function residentReportHtml(n){const s=residentWealth(n),home=data.locaties.find(l=>l.id===n.location),work=data.locaties.find(l=>l.id===n.workplace),table=(headers,rows)=>`<div class="finance-table-wrap"><table class="finance-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Geen gegevens.</td></tr>`}</tbody></table></div>`;return `<div class="resident-report-html"><section class="report-civil-records"><h3>Akten</h3>${residentCivilRecords(n.id).length?'<ul>'+residentCivilRecords(n.id).map(r=>'<li>'+esc(r.number+' · '+r.title+' · '+r.date.label+(r.status==='withdrawn'?' · Ingetrokken':''))+'</li>').join('')+'</ul>':'<p>Geen akten gekoppeld.</p>'}</section>${civilMarriageText(n.id)?'<p class="report-marriage">'+esc(civilMarriageText(n.id))+'</p>':''}<p><b>Woonplek:</b> ${esc(home?.name||(n.npc?'Geen slaapplek toegewezen':lodgingName()))}<br><b>Werkplek:</b> ${esc(work?.name||(n.workplace==='__travel__'?'Op reis':'Geen'))}</p><div class="report-summary"><div><small>Rijkdom</small><b>${gp(s.wealth)}</b></div><div><small>Bank</small><b>${gp(s.bank)}</b></div><div><small>Netto / week</small><b>${gp(s.net)}</b></div></div><p>${gp(s.income)} omzet − ${gp(s.upkeep)} kosten per week. Overnachtingen: ${gp(s.lodging)} per week.</p><h3>Eigendom</h3>${table(['Pand','Waarde','Omzet / week','Kosten / week'],s.assets.map(r=>{const a=assetFinance(r);return [r.name,gp(a.build),gp(a.income),gp(a.upkeep)]}))}<p><b>Grond:</b> ${s.cells} vakjes · ${s.plots.length} ${s.plots.length===1?'perceel':'percelen'} · ${gp(s.plotCost)}</p>${table(['Perceel','Vakken'],s.plots.map(p=>[plotLabel(p),plotCells(p).length]))}<h3>Betalingen</h3>${table(['Week','Omschrijving','Soort voor inwoner','Bedrag','Status'],residentLedger(n.id).map(t=>[t.week,t.label,t.direction,gp(t.amount),t.status]))}</div>`}
function addPaymentRegistration(){if(financeTab!=='payouts')return;const f=ensureFinance(),week=Math.max(1,Number(f.payoutWeek)||Math.max(1,timelinePaymentWeek())),box=document.createElement('section');box.innerHTML=`<h2>Ontvangen en gedane betalingen</h2><form id="residentTransaction" class="expense-form"><label>Inwoner<select name="residentId" required>${data.inwoners.map(n=>`<option value="${esc(n.id)}" ${n.id===financeOwner?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label><label>Omschrijving<input name="label" required maxlength="120"></label><label>Richting vanuit inwoner<select name="direction"><option value="gedaan">Betaling van inwoner ontvangen</option><option value="ontvangen">Betaling aan inwoner gedaan</option></select></label><label>Bedrag (gp)<input name="amount" type="number" min=".01" step=".01" required></label><label>Campagneweek<input name="week" type="number" min="1" max="${Math.max(1,timelinePaymentWeek())}" step="1" value="${week}" required></label><button class="primary">Registreren</button></form><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Week</th><th>Inwoner</th><th>Omschrijving</th><th>Richting</th><th>Bedrag</th></tr></thead><tbody>${(f.transactions||[]).filter(t=>t.week<=timelinePaymentWeek()).filter(t=>financeOwner==='all'||t.residentId===financeOwner).map(t=>`<tr><td>${t.week}</td><td>${esc(data.inwoners.find(n=>n.id===t.residentId)?.name||'Onbekend')}</td><td>${esc(t.label)}</td><td>${t.direction==='gedaan'?'Van inwoner ontvangen':'Aan inwoner betaald'}</td><td>${gp(t.amount)}</td></tr>`).join('')||'<tr><td colspan="5">Nog geen losse betalingen geregistreerd.</td></tr>'}</tbody></table></div>`;$('#financeBody').append(box);$('#residentTransaction').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);if(Number(form.get('week'))>timelinePaymentWeek()){toast('Deze week ligt na de huidige tijdlijnweek.');return}if(!data.inwoners.some(n=>n.id===form.get('residentId')))return;const resident=data.inwoners.find(n=>n.id===form.get('residentId')),bankChange=(form.get('direction')==='gedaan'?-1:1)*Number(form.get('amount'));if(Number(resident.bankGp||0)+bankChange<0){toast('Onvoldoende banksaldo.');return}resident.bankGp=Number(resident.bankGp||0)+bankChange;(f.transactions??=[]).push({bankDeltas:[{id:resident.id,amount:bankChange}],id:crypto.randomUUID(),residentId:form.get('residentId'),label:String(form.get('label')).trim(),direction:form.get('direction'),amount:Number(form.get('amount')),week:Number(form.get('week')),campaignDay:data.day});persist();render()}}

function syncStaffNpcs(){const f=ensureFinance();let changed=false;for(const r of data.locaties){const rule=f.assets[r.id]||{},staff=f.staff.find(t=>t.id===rule.staff);if(!staff||staff.id==='none'||staff.ownerLevel)continue;let n=data.inwoners.find(n=>n.id===rule.staffResidentId);if(!n)n=data.inwoners.find(n=>n.workplace===r.id&&n.id!==r.ownerId);if(!n){n={id:crypto.randomUUID(),name:'Medewerker van '+r.name,kind:staff.name,description:'',secret:'',npc:true,workplace:r.id,age:'',race:'',characterClass:''};data.inwoners.push(n);changed=true}if(n.workplace&&n.workplace!==r.id){if(rule.staffResidentId||rule.staff!=='none')changed=true;rule.staffResidentId='';rule.staff='none'}else{if(rule.staffResidentId!==n.id||n.workplace!==r.id)changed=true;rule.staffResidentId=n.id;n.workplace=r.id}f.assets[r.id]=rule}if(changed)persist()}
function prepareNpcDetails(r){$('#extra').insertAdjacentHTML('beforeend',`<fieldset><legend>Personagegegevens</legend><label>Leeftijd<input name="age" type="number" min="0" step="1" value="${esc(r.age||'')}"></label><label>Ras<input name="race" value="${esc(r.race||'')}" maxlength="80"></label><label>Klas<input name="characterClass" value="${esc(r.characterClass||'')}" maxlength="80"></label></fieldset>`)}
function enhanceNpcDetails(){if(view==='inwoners')document.querySelectorAll('#content .card').forEach(card=>{const n=data.inwoners.find(n=>n.id===card.dataset.id);if(n&&n.npc)card.querySelector('h2').insertAdjacentHTML('afterend',`<p>${['NPC'].filter(Boolean).map(esc).join(' · ')}</p>`)});if(financeTab==='buildings'&&view==='finance')document.querySelectorAll('select[data-field="staff"]').forEach(el=>{const n=data.inwoners.find(n=>n.id===ensureFinance().assets[el.dataset.asset]?.staffResidentId);if(n){const b=document.createElement('button');b.textContent=n.name+' bewerken';b.onclick=()=>edit('inwoners',n.id);el.parentElement.append(b)}})}

function activeSalaryJobs(){const f=ensureFinance();return data.locaties.flatMap(r=>{const rule=f.assets[r.id]||{},a=assetFinance(r),employee=data.inwoners.find(n=>n.id===rule.staffResidentId);return employee&&employee.id!==r.ownerId&&a.profile.workshop&&a.staff.id!=='none'&&!a.staff.ownerLevel?[{assetId:r.id,residentId:employee.id,employerId:r.ownerId||'',label:'Salaris — '+r.name,amount:Number(a.staff.wage),personalSalary:!!a.staff.personalSalary}]:[]})}
function periodText(text){return calendarConfig().system==='harptos'?text.replace(/week/g,'tenday').replace(/Week/g,'Tenday'):text}
function residentReport(n){const text=residentReportRaw(n),newline=text.indexOf('\n');return periodText(text.slice(0,newline+1)+reportStatusMarkdown(n)+text.slice(newline+1))}
function financeExportText(format){const result=financeExportTextRaw(format);if(format!=='json')result.text=periodText(result.text);return result}
function paymentPeriodDays(){return calendarConfig().system==='harptos'?10:7}
function harptosMonthPosition(date){let index=harptosMonths.indexOf(date.month);if(index<0){const segments=harptosSegments(date.year),position=segments.findIndex(s=>s.name===date.month);index=harptosMonths.indexOf(segments.slice(0,position).reverse().find(s=>harptosMonths.includes(s.name)).name)}return (date.year-1)*12+index}
function paymentAnchor(){const days=data.tijdlijn.map(r=>Number(r.day)).filter(d=>Number.isInteger(d)&&d>0);return campaignDate(days.length?Math.min(...days):1)}
function paymentScope(){if(calendarConfig().system!=='harptos')return '';const date=paymentAnchor(),position=harptosMonthPosition(date);return 'harptos-'+(Math.floor(position/12)+1)+'-'+harptosMonths[position%12]+'|'}
function paymentPeriodEndDay(period){if(calendarConfig().system!=='harptos')return period*7;const position=harptosMonthPosition(paymentAnchor())+Math.floor((period-1)/3),date={year:Math.floor(position/12)+1,month:harptosMonths[position%12],day:((period-1)%3+1)*10};return harptosOrdinal(date)-harptosOrdinal(calendarConfig().harptosStart)+1}
function timelinePaymentWeek(){const days=data.tijdlijn.map(r=>Number(r.day)).filter(d=>Number.isInteger(d)&&d>0);if(!days.length)return 0;const day=Math.max(...days);if(calendarConfig().system==='harptos'){const date=campaignDate(day),months=harptosMonthPosition(date)-harptosMonthPosition(paymentAnchor()),completed=harptosMonths.includes(date.month)?Math.floor((date.day-1)/10):3;return Math.max(0,months*3+completed)}return Math.floor((day-1)/7)}

function prepareTimelinePayments(){for(let week=1;week<=timelinePaymentWeek();week++)preparePayoutWeek(week)}
function processWeeklySalaries(){const f=ensureFinance(),week=timelinePaymentWeek(),scope=paymentScope(),jobsByWeek=new Map();f.salaryPayments??={};let changed=false;for(let w=1;w<=week;w++){const jobs=datedSalaryJobs(paymentPeriodEndDay(w));jobsByWeek.set(w,jobs);for(const job of jobs){const key=scope+w+':'+job.assetId,existing=f.salaryPayments[key];if(!existing){f.salaryPayments[key]={...job,scope,week:w,paid:false,campaignDay:currentEffectiveDay()};changed=true}else if(!existing.paid&&!existing.cashApplied&&!existing.ownerCashApplied&&!existing.cancelled&&!existing.balanceDeltas&&(job.personalSalary||existing.personalSalary)){for(const [field,value]of Object.entries(job))if(existing[field]!==value){existing[field]=value;changed=true}}}}for(const payment of Object.values(f.salaryPayments)){const employee=data.inwoners.find(n=>n.id===payment.residentId);if(!employee||employee.npc||!payment.personalSalary||payment.paid||payment.ownerCashApplied||payment.cashApplied||payment.balanceDeltas||(payment.scope||'')!==scope||payment.week>week)continue;const expected=jobsByWeek.get(payment.week)?.find(job=>job.residentId===payment.residentId&&job.assetId===payment.assetId);if(!expected&&!payment.cancelled){payment.cancelled=true;payment.agreementInactive=true;changed=true}else if(expected&&payment.agreementInactive){Object.assign(payment,expected);payment.cancelled=false;delete payment.agreementInactive;changed=true}}if(f.salaryProcessedWeek!==week){f.salaryProcessedWeek=week;changed=true}if(changed)persist()}

function salaryLedger(id){return Object.values(ensureFinance().salaryPayments||{}).filter(p=>!p.cancelled&&(p.residentId===id||p.employerId===id)&&(p.scope||'')===paymentScope()&&p.week<=timelinePaymentWeek()).map(p=>({...p,direction:p.residentId===id?'ontvangen':'gedaan',status:p.ownerCashApplied?'Betaald door eigenaar':p.paid?'Nog verrekenen met eigenaar':'Openstaand'}))}
function renderSalaryPayments(){if(view!=='finance'||financeTab!=='payouts')return;const f=ensureFinance(),payments=Object.entries(f.salaryPayments||{}).filter(([,p])=>(p.scope||'')===paymentScope()&&p.week<=timelinePaymentWeek()&&(financeOwner==='all'||p.residentId===financeOwner||p.employerId===financeOwner)).sort((a,b)=>b[1].week-a[1].week),section=document.createElement('section');section.innerHTML=`<h2>Medewerkersloon</h2><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Periode</th><th>Medewerker</th><th>Eigenaar</th><th>Werkplek</th><th>Salaris</th><th>Status</th><th></th></tr></thead><tbody>${payments.map(([key,p])=>`<tr><td>${p.week}</td><td>${esc(data.inwoners.find(n=>n.id===p.residentId)?.name||'Onbekend')}</td><td>${esc(data.inwoners.find(n=>n.id===p.employerId)?.name||'Geen eigenaar')}</td><td>${esc(p.label.replace(/^Salaris — /,''))}</td><td>${gp(p.amount)}</td><td>${p.ownerCashApplied?'Betaald':p.paid?'Nog verrekenen met eigenaar':'Openstaand'}</td><td>${p.ownerCashApplied?'':`<button data-pay-salary="${esc(key)}" ${!p.employerId?'disabled':''}>Eigenaar betaalt via bank</button>`}</td></tr>`).join('')||'<tr><td colspan="7">Geen medewerkersloon geregistreerd.</td></tr>'}</tbody></table></div>`;$('#financeBody').append(section);document.querySelectorAll('[data-pay-salary]').forEach(b=>b.onclick=()=>{const result=settleSalary(f.salaryPayments[b.dataset.paySalary]);if(!result.ok){toast(result.message);return}persist();render()})}


let datedBaselineReady=false;
function currentEffectiveDay(){return Math.max(1,...data.tijdlijn.map(r=>Number(r.day)||1))}
function datedEntities(){return [...data.locaties.map(r=>({type:'locaties',record:r})),...data.inwoners.map(r=>({type:'inwoners',record:r})),...(data.map?.plots||[]).map(r=>({type:'plots',record:r}))]}

function withDatedState(day,fn){const live=data,d={...live};if(live.finance)d.finance={...live.finance,assets:{...live.finance.assets},catalog:live.finance.catalog?.map(p=>({...p})),staff:live.finance.staff?.map(p=>({...p}))};if(live.map)d.map={...live.map};for(const type of ['locaties','inwoners','plots']){const rows=(type==='plots'?live.map?.plots:live[type])||[],historical=rows.flatMap(r=>{const key=type+':'+r.id,baseline=live.entityHistoryBaselines?.[key];let match=baseline&&baseline.day<=day?baseline:null,hasHistory=!!baseline;for(const entry of live.entityHistory?.[key]||[]){hasHistory=true;if(entry.day<=day&&(!match||entry.day>=match.day))match=entry}if(!hasHistory)return [{...r}];if(!match)return [];if(type==='locaties'&&d.finance)d.finance.assets[r.id]={...match.finance};return [{...match.state}]});if(type==='plots'){if(d.map)d.map.plots=historical}else d[type]=historical}try{data=d;return fn()}finally{data=live}}
function datedResidentFinance(id,day){return withDatedState(day,()=>residentFinance(id))}
function datedSalaryJobs(day){return withDatedState(day,()=>activeSalaryJobs())}
function openEntityDates(filterKey=null){let dialog=$('#entityDates');if(!dialog){dialog=document.createElement('dialog');dialog.id='entityDates';dialog.style.width='850px';document.body.append(dialog)}dialog.innerHTML=`<h2>Ingangsdatums en wijzigingen</h2><p>Hier staan wijzigingen van panden, percelen en inwoners. Een nieuwe uitgangssituatie blijft op de achtergrond bewaard, zonder wijzigingsregels opnieuw aan te maken. Woonplek, werkplek en eigendom worden op hun gekozen ingangsdatum vastgelegd. Geldmutaties staan in het kasboek.</p><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Onderdeel</th><th>Datum</th><th>Wijziging</th></tr></thead><tbody>${Object.entries(data.entityHistory||{}).filter(([key])=>['locaties','plots','inwoners'].includes(key.split(':')[0])&&(!filterKey||key===filterKey)).flatMap(([key,entries])=>entries.map((e,i)=>i>0&&describeEntityChange(historyPrevious(entries,i,data.entityHistoryBaselines?.[key]),e)==='Geen inhoudelijke wijziging'?'':`<tr><td>${esc(e.state.name||'Perceel')}</td><td><button data-date-key="${esc(key)}" data-date-index="${i}">${esc(calendarLabel(e.day))}</button></td><td>${i===0&&!data.entityHistoryBaselines?.[key]?(key.startsWith('inwoners:')?'Aankomst':key.startsWith('locaties:')?'Bouwdatum':'Perceel aangemaakt')+(e.legacy?' (nog controleren)':''):esc(describeEntityChange(historyPrevious(entries,i,data.entityHistoryBaselines?.[key]),e))}</td></tr>`)).join('')}</tbody></table></div><button id="closeEntityDates">Sluiten</button>`;$('#closeEntityDates').onclick=()=>dialog.close();document.querySelectorAll('[data-date-key]').forEach(b=>b.onclick=()=>editEntityDate(b.dataset.dateKey,Number(b.dataset.dateIndex)));historyFilterAndDelete();enableHistorySorting();polishActionIcons();if(!dialog.open)dialog.showModal()}
function editEntityDate(key,index){const entry=data.entityHistory[key][index],c=calendarConfig();let dialog=$('#entityDateEditor');if(!dialog){dialog=document.createElement('dialog');dialog.id='entityDateEditor';document.body.append(dialog)}dialog.innerHTML=`<form id="entityDateForm"><h2>Datum wijzigen</h2>${dateFields('entityEffective',campaignDate(entry.day),c.system)}<div class="form-actions"><button type="button" id="cancelEntityDate">Annuleren</button><button class="primary">Bewaren</button></div></form>`;bindDateFields('entityEffective');$('#cancelEntityDate').onclick=()=>dialog.close();$('#entityDateForm').onsubmit=e=>{e.preventDefault();try{const date=readDateFields('entityEffective',c.system),day=c.system==='gregorian'?Math.round((Date.parse(date)-Date.parse(c.gregorianStart))/86400000)+1:harptosOrdinal(date)-harptosOrdinal(c.harptosStart)+1;if(day<1||day>currentEffectiveDay())throw Error();entry.day=day;entry.legacy=false;persist();dialog.close();openEntityDates()}catch{toast('Kies een datum tussen het begin en de huidige tijdlijndatum.')}};dialog.showModal()}
function addEntityDateControls(){if(player)return;const container=view==='finance'?$('.finance-toolbar'):['inwoners','locaties'].includes(view)?$('.toolbar'):null;if(!container)return;const button=document.createElement('button');button.textContent='Ingangsdatums & historie';button.onclick=()=>openEntityDates();container.append(button)}

function localizePaymentPeriods(){if(calendarConfig().system!=='harptos')return;const roots=[$('#stats'),$('#content'),$('#residentReport')].filter(Boolean);for(const root of roots){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes)node.textContent=node.textContent.replace(/Campagneweek/g,'Tenday').replace(/campagneweek/g,'tenday').replace(/Weekoverzicht/g,'Tendayoverzicht').replace(/Week tonen/g,'Tenday tonen').replace(/Week openen/g,'Tenday openen').replace(/week/g,'tenday').replace(/Week/g,'Tenday').replace(/Zeven nachten/g,'Tien nachten');}document.querySelectorAll('[title]').forEach(el=>el.title=el.title.replace(/week/g,'tenday'));}
function applySalaryCash(){const f=ensureFinance();for(const p of Object.values(f.salaryPayments||{})){if(!p.paid||p.cashApplied||p.balanceDeltas||p.paymentAccount||(p.scope||'')!==paymentScope()||p.week>timelinePaymentWeek())continue;const employee=data.inwoners.find(n=>n.id===p.residentId);if(!employee?.npc)continue;employee.cashGp=Number(employee.cashGp||0)+Number(p.amount||0);p.cashApplied=true;p.cashAppliedDay=currentEffectiveDay();}}
function describeEntityChange(before,after){const labels={name:'Naam',kind:'Type / rol',description:'Omschrijving',secret:'DM-geheim',ownerId:'Eigenaar',location:'Woonplek',workplace:'Werkplek',cashGp:'Contant geld',bankGp:'Bankgeld',age:'Leeftijd',race:'Ras',characterClass:'Klas',npc:'NPC',hidden:'Spelerzichtbaarheid',footprint:'Pandvorm / formaat',cells:'Perceelvakken',profile:'Regelprofiel',staff:'Personeelsniveau',staffResidentId:'Medewerker',ownerWorks:'Eigenaar werkt mee',salaryOverrideGp:'Persoonlijk salaris (gp per periode)',employmentEmployerId:'Werkgever',employmentWageGp:'Afgesproken salaris (gp per periode)',modules:'Uitbreidingen',incomeOverride:'Opbrengst',upkeepOverride:'Kosten',costOverride:'Waarde',appearance:'Pandstijl',acquisition:'Aankoopgegevens'};const display=(key,value)=>{if(key==='salaryOverrideGp'&&(value===undefined||value===null||value===''))return 'Standaardtarief';if(value===undefined||value===null||value==='')return 'Geen';if(value==='__travel__')return 'Op reis';if(value==='__lodging__')return 'Automatisch verblijf';if(value==='__unhoused_npc__')return 'Geen vaste woonplek (NPC)';if(['ownerId','location','workplace','staffResidentId','employmentEmployerId'].includes(key))return [...data.inwoners,...data.locaties].find(r=>r.id===value)?.name||String(value);if(key==='cells')return value.length+' vakjes';if(key==='footprint')return value.w+' × '+value.h+' vakjes';if(key==='profile'||key==='staff')return [...ensureFinance().catalog,...ensureFinance().staff].find(r=>r.id===value)?.name||String(value);if(typeof value==='object')return JSON.stringify(value);return String(value)};const changes=[];for(const [old,next]of [[before.state,after.state],[before.finance||{},after.finance||{}]])for(const key of new Set([...Object.keys(old),...Object.keys(next)])){if(['id','effectiveDay','bankGp','cashGp'].includes(key)||JSON.stringify(old[key])===JSON.stringify(next[key]))continue;changes.push((labels[key]||key)+': '+display(key,old[key])+' → '+display(key,next[key]))}return changes.join('; ')||'Geen inhoudelijke wijziging';}

function addResidentSummaryTips(n){const s=residentWealth(n),details=[`Panden ${gp(s.value-s.plotCost)} + grond ${gp(s.plotCost)} + bank ${gp(s.bank)} = ${gp(s.wealth)}. Contant geld wordt buiten deze app bijgehouden.`,'Bijgehouden banksaldo: '+gp(s.bank),`Omzet ${gp(s.income)} − kosten ${gp(s.upkeep)} = ${gp(s.net)} per periode.`];document.querySelectorAll('#residentReport .report-summary>div').forEach((box,i)=>{box.classList.add('summary-explained');box.tabIndex=0;const tip=document.createElement('div');tip.className='stat-breakdown';tip.textContent=details[i]||'';tip.setAttribute('role','tooltip');box.append(tip)})}
function paymentTotals(){const f=ensureFinance(),groups=new Map(),add=(id,direction,amount,record,kind)=>{const key=id+':'+direction+':'+kind;let group=groups.get(key);if(!group){group={id,direction,kind,amount:0,records:[]};groups.set(key,group)}group.amount+=Number(amount||0);group.records.push(record)};for(const [key,p]of Object.entries(f.payouts||{})){if(!key.startsWith(paymentScope()))continue;const [period,...rest]=key.slice(paymentScope().length).split(':');if(Number(period)>timelinePaymentWeek()||p.paid||p.cancelled||Number(p.amount)<=0)continue;const id=rest.join(':');if(financeOwner!=='all'&&financeOwner!==id)continue;add(id,p.direction==='inbound'?'ontvangen':'betalen',p.amount,p,'inwoner')}for(const p of Object.values(f.salaryPayments||{})){if((p.scope||'')!==paymentScope()||p.week>timelinePaymentWeek()||p.ownerCashApplied)continue;if(financeOwner!=='all'&&financeOwner!==p.residentId&&financeOwner!==p.employerId)continue;add(p.residentId,'betalen',p.amount,p,'salaris')}return [...groups.values()]}
function renderPaymentTotals(){if(view!=='finance'||financeTab!=='payouts')return;$('#paymentOverview')?.remove();const section=document.createElement('section');section.id='paymentOverview';section.innerHTML='<div class="payout-toolbar"><button id="totalSelectAll">Alle inwoners meenemen</button><button id="totalExport">↓ Totalen (.md)</button></div><div class="finance-table-wrap"><table class="finance-table payment-overview"><thead></thead><tbody></tbody></table></div><p id="paymentGrandTotals"></p>';$('#financeBody').prepend(section);$('#totalSelectAll').onclick=()=>{const f=ensureFinance();data.inwoners.filter(n=>!n.npc).forEach(n=>f.payoutRecipients[n.id]=true);prepareTimelinePayments();persist();render()};$('#totalExport').onclick=()=>downloadData('# Openstaande totalen — '+data.villageName+'\n\n| Inwoner | Soort | Bedrag |\n| --- | --- | ---: |\n'+paymentTotals().map(g=>'| '+String(data.inwoners.find(n=>n.id===g.id)?.name||'Onbekend').replace(/\|/g,'\\|')+' | '+g.kind+' — '+g.direction+' | '+gp(g.amount)+' |').join('\n'),'betalingen-totalen.md','text/markdown;charset=utf-8')}

function employerSalaryGroups(){const groups=new Map();for(const p of Object.values(ensureFinance().salaryPayments||{})){if((p.scope||'')!==paymentScope()||p.week>timelinePaymentWeek()||p.ownerCashApplied||p.cancelled||!p.employerId)continue;const group=groups.get(p.employerId)||{id:p.employerId,amount:0,records:[]};group.amount+=Number(p.amount||0);group.records.push(p);groups.set(p.employerId,group)}return [...groups.values()].filter(g=>financeOwner==='all'||financeOwner===g.id)}

function renderEmployerSalaryButtons(){if(view!=='finance'||financeTab!=='payouts')return;const table=$('#paymentOverview table');if(!table)return;const salaryGroups=employerSalaryGroups(),totals=paymentTotals(),invoices=ensureFinance().purchaseInvoices||[],residents=data.inwoners.filter(n=>(!n.npc||invoices.some(p=>p.residentId===n.id)||salaryGroups.some(g=>g.id===n.id))&&(financeOwner==='all'||financeOwner===n.id));table.tHead.innerHTML='<tr><th>Inwoner</th><th>Te betalen</th><th>Te ontvangen</th><th>Medewerkersloon</th><th>Acties</th></tr>';table.tBodies[0].innerHTML=residents.map(n=>{const pay=totals.find(g=>g.id===n.id&&g.kind==='inwoner'&&g.direction==='betalen'),receive=totals.find(g=>g.id===n.id&&g.kind==='inwoner'&&g.direction==='ontvangen'),salary=salaryGroups.find(g=>g.id===n.id),bills=invoices.filter(p=>p.residentId===n.id);return `<tr><td>${esc(n.name)}</td><td>${gp(pay?.amount||0)}</td><td>${gp(receive?.amount||0)}</td><td>${gp(salary?.amount||0)}${salary?'<small>'+[...new Set(salary.records.map(p=>data.inwoners.find(n=>n.id===p.residentId)?.name||'Onbekend'))].map(esc).join(', ')+'</small>':''}</td><td><div class="payment-actions"><button data-pay-all-resident="${esc(n.id)}" ${pay?.amount>0?'':'disabled'}>Totaal betaald</button><button data-receive-all-resident="${esc(n.id)}" ${receive?.amount>0?'':'disabled'}>Totaal ontvangen</button><button data-owner-salary="${esc(n.id)}" ${salary?.amount>0?'':'disabled'}>Salaris betalen</button><button data-resident-invoices="${esc(n.id)}" ${bills.length?'':'disabled'}>Rekeningen (${bills.length})</button></div></td></tr>`}).join('')||'<tr><td colspan="5">Geen inwoners gevonden.</td></tr>';table.querySelectorAll('[data-owner-salary]').forEach(b=>b.onclick=()=>openSalaryPaymentDialog(b.dataset.ownerSalary));table.querySelectorAll('[data-resident-invoices]').forEach(b=>b.onclick=()=>openResidentInvoices(b.dataset.residentInvoices));for(const [attr,direction]of [['pay-all-resident','betalen'],['receive-all-resident','ontvangen']])table.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>{const id=b.getAttribute('data-'+attr),group=paymentTotals().find(g=>g.id===id&&g.kind==='inwoner'&&g.direction===direction);if(!group)return;const result=settleBankPayments(id,group.records);if(!result.ok){toast(result.message);return}persist();render()});$('#paymentGrandTotals').textContent='Totaal te betalen: '+gp(totals.filter(g=>g.direction==='betalen').reduce((sum,g)=>sum+g.amount,0))+' · te ontvangen: '+gp(totals.filter(g=>g.direction==='ontvangen').reduce((sum,g)=>sum+g.amount,0))}

function cashbookEntries(){const f=ensureFinance(),name=id=>data.inwoners.find(n=>n.id===id)?.name||'Onbekend';return [...Object.entries(f.salaryPayments||{}).filter(([,p])=>p.paid||p.cashApplied||p.ownerCashApplied).map(([key,p])=>({kind:'salary',key,day:p.paidDay||p.campaignDay||1,period:(p.scope||'')+p.week,label:p.label,from:name(p.employerId),to:name(p.residentId),amount:p.amount,bank:p.paymentAccount==='bank',cash:p.paymentAccount==='cash'||(!p.paymentAccount&&!!(p.cashApplied||p.ownerCashApplied))})),...Object.entries(f.payouts||{}).filter(([,p])=>p.paid||p.received).map(([key,p])=>{const id=key.slice(key.indexOf('|')+1).split(':').slice(1).join(':');return {kind:'payout',key,day:p.paidDay||p.receivedDay||p.campaignDay||1,period:key.split(':')[0],label:payoutDescription(id,p),from:p.direction==='inbound'?name(id):'Kanselarij',to:p.direction==='inbound'?'Kanselarij':name(id),amount:p.amount,bank:!!p.bankDeltas||p.balanceDeltas?.some(d=>d.field==='bankGp'),cash:!!p.balanceDeltas?.some(d=>d.field==='cashGp')}}),...(f.transactions||[]).map(p=>({kind:'transaction',key:p.id,day:p.campaignDay||1,period:p.week,label:p.label,from:p.direction==='gedaan'?name(p.residentId):'Kanselarij',to:p.toResidentId?name(p.toResidentId):p.direction==='gedaan'?'Kanselarij':name(p.residentId),amount:p.amount,bank:!!p.bankDeltas||p.balanceDeltas?.some(d=>d.field==='bankGp'),cash:!!p.balanceDeltas?.some(d=>d.field==='cashGp')}))].sort((a,b)=>b.day-a.day)}
function removeCashbookEntry(kind,key){const f=ensureFinance();if(kind==='transaction'){const transaction=f.transactions.find(t=>t.id===key);if(transaction?.balanceDeltas){for(const d of transaction.balanceDeltas){const n=data.inwoners.find(n=>n.id===d.id);if(!n||Number(n[d.field]||0)-d.amount<0)return {ok:false,message:'Onvoldoende saldo om de geldmutatie terug te draaien.'}}for(const d of transaction.balanceDeltas){const n=data.inwoners.find(n=>n.id===d.id);n[d.field]=Number(n[d.field]||0)-d.amount}}if(transaction?.bankDeltas){const result=reverseBankDeltas(transaction.bankDeltas);if(!result.ok)return result;}f.transactions=f.transactions.filter(t=>t.id!==key);return {ok:true}}if(kind==='payout'){const p=f.payouts[key];if(p?.bankDeltas){const result=reverseBankDeltas(p.bankDeltas);if(!result.ok)return result;delete p.bankDeltas;}if(!p)return {ok:false,message:'Betaling niet gevonden.'};p.paid=false;p.received=false;delete p.paidDay;delete p.receivedDay;return {ok:true}}const p=f.salaryPayments[key];if(!p)return {ok:false,message:'Betaling niet gevonden.'};if(p.balanceDeltas){for(const d of p.balanceDeltas){const n=data.inwoners.find(n=>n.id===d.id);if(!n||Number(n[d.field]||0)-d.amount<0)return {ok:false,message:'Onvoldoende saldo op de oorspronkelijke rekening om het salaris terug te draaien.'}}for(const d of p.balanceDeltas){const n=data.inwoners.find(n=>n.id===d.id);n[d.field]=Number(n[d.field]||0)-d.amount}p.paid=false;p.cashApplied=false;p.ownerCashApplied=false;delete p.balanceDeltas;delete p.paymentAccount;delete p.paidDay;delete p.cashAppliedDay;return {ok:true}}const employee=data.inwoners.find(n=>n.id===p.residentId),owner=data.inwoners.find(n=>n.id===p.employerId);if(p.cashApplied&&(!employee||Number(employee.cashGp||0)<p.amount))return {ok:false,message:'De medewerker heeft onvoldoende contant geld om deze betaling terug te draaien.'};if(p.ownerCashApplied&&!owner)return {ok:false,message:'De eigenaar ontbreekt; herstel de koppeling voordat je de betaling verwijdert.'};if(p.cashApplied)employee.cashGp=Number(employee.cashGp||0)-p.amount;if(p.ownerCashApplied)owner.cashGp=Number(owner.cashGp||0)+p.amount;p.paid=false;p.cashApplied=false;p.ownerCashApplied=false;delete p.paidDay;delete p.cashAppliedDay;return {ok:true}}
function renderCashbook(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#heading').textContent='Kasboek';$('#subtitle').textContent='Alle geregistreerde betalingen.';$('#add').hidden=true;$('#stats').innerHTML='';const entries=cashbookEntries();$('#content').innerHTML=`<div class="toolbar"><button id="cashbookExport">↓ Export MD</button></div><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Datum</th><th>Periode</th><th>Omschrijving</th><th>Van</th><th>Naar</th><th>Bedrag</th><th>Verwerking</th><th></th></tr></thead><tbody>${entries.map((p,i)=>`<tr><td>${esc(calendarLabel(p.day))}</td><td>${esc(p.period)}</td><td>${esc(p.label)}</td><td>${esc(p.from)}</td><td>${esc(p.to)}</td><td>${gp(p.amount)}</td><td>${p.cash&&p.bank?'Bank en contant verwerkt':p.cash?'Contant verwerkt':p.bank?'Bank verwerkt':'Registratie'}</td><td><button data-delete-payment="${i}">Verwijderen</button></td></tr>`).join('')||'<tr><td colspan="8">Nog geen betalingen geregistreerd.</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-delete-payment]').forEach(b=>b.onclick=()=>{const p=entries[Number(b.dataset.deletePayment)];if(!confirm('Deze betaling verwijderen? Een verwerkte salarisbetaling wordt via de oorspronkelijke rekening teruggedraaid; de verplichting komt weer open te staan.'))return;const result=removeCashbookEntry(p.kind,p.key);if(!result.ok){toast(result.message);return}persist();render()});$('#cashbookExport').onclick=()=>downloadData('# Kasboek — '+data.villageName+'\n\n| Datum | Omschrijving | Van | Naar | Bedrag |\n| --- | --- | --- | --- | ---: |\n'+entries.map(p=>[calendarLabel(p.day),p.label,p.from,p.to,gp(p.amount)].map(v=>String(v).replace(/\|/g,'\\|').replace(/\n/g,' ')).join(' | ')).map(r=>'| '+r+' |').join('\n'),'kasboek.md','text/markdown;charset=utf-8')}

function entityCreationLabel(type,id){const entries=data.entityHistory?.[type+':'+id]||[],first=entries[0];return first?calendarLabel(first.day)+(first.legacy?' (voorlopig)':''):'Nog niet vastgelegd'}
function showEntityDatesOnCards(){if(!['inwoners','locaties'].includes(view))return;document.querySelectorAll('#content .card').forEach(card=>{const date=document.createElement('p');date.className='entity-date';date.textContent=(view==='inwoners'?'Aankomst: ':'Gebouwd: ')+entityCreationLabel(view,card.dataset.id);const target=card.querySelector('.rank-person')||card;target.append(date)})}
function renderPlotPage(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#heading').textContent='Percelen van '+data.villageName;$('#subtitle').textContent='Grond, eigenaars en aanmaakdatums.';$('#add').hidden=true;$('#stats').innerHTML='';const plots=(data.map?.plots||[]).filter(p=>!player);$('#content').innerHTML=`<div class="toolbar"><input id="plotSearch" placeholder="Zoek in percelen…" value="${esc(query)}"></div><div class="cards">${plots.filter(p=>(plotLabel(p)+' '+(data.inwoners.find(n=>n.id===p.ownerId)?.name||'')).toLowerCase().includes(query.toLowerCase())).map(p=>`<article class="card" data-plot-card="${esc(p.id)}" tabindex="0" role="button"><span class="tag">PERCEEL</span><h2>${esc(plotLabel(p))}</h2><p><b>Formaat:</b> ${plotCells(p).length} vakjes · 1 perceel</p><p><b>Eigenaar:</b> ${esc(data.inwoners.find(n=>n.id===p.ownerId)?.name||'Geen eigenaar')}</p><p><b>Aangemaakt:</b> ${esc(entityCreationLabel('plots',p.id))}</p><button data-plot-dates="${esc(p.id)}">Aanmaakdatum & historie</button></article>`).join('')||'<p>Geen percelen gevonden.</p>'}</div>`;$('#plotSearch').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#plotSearch').focus();$('#plotSearch').setSelectionRange(pos,pos)};document.querySelectorAll('[data-plot-card]').forEach(card=>{card.onclick=()=>editPlot(card.dataset.plotCard);card.onkeydown=e=>{if(e.key==='Enter')editPlot(card.dataset.plotCard)}});document.querySelectorAll('[data-plot-dates]').forEach(b=>b.onclick=e=>{e.stopPropagation();openEntityDates('plots:'+b.dataset.plotDates)})}

function renderCashbookTab(){const content=$('#content'),toolbar=content.querySelector('.finance-toolbar'),body=$('#financeBody'),savedStats=$('#stats').innerHTML;renderCashbook();const markup=content.innerHTML;const temp=document.createElement('div');temp.innerHTML=markup;content.replaceChildren(toolbar);body.innerHTML='';while(temp.firstChild)body.append(temp.firstChild);content.append(body);$('#heading').textContent='Kanselarij';$('#stats').innerHTML=savedStats;const entries=cashbookEntries();document.querySelectorAll('[data-delete-payment]').forEach(b=>b.onclick=()=>{const p=entries[Number(b.dataset.deletePayment)];if(!confirm('Deze betaling verwijderen? Eventuele geboekte saldomutaties worden teruggedraaid.'))return;const result=removeCashbookEntry(p.kind,p.key);if(!result.ok){toast(result.message);return}persist();render()});$('#cashbookExport').onclick=()=>downloadData('# Kasboek — '+data.villageName+'\n\n| Datum | Omschrijving | Van | Naar | Bedrag |\n| --- | --- | --- | --- | ---: |\n'+entries.map(p=>'| '+[calendarLabel(p.day),p.label,p.from,p.to,gp(p.amount)].map(v=>String(v).replace(/\|/g,'\\|').replace(/\n/g,' ')).join(' | ')+' |').join('\n'),'kasboek.md','text/markdown;charset=utf-8')}
function cleanLegacyPayroll(){if(calendarConfig().system!=='harptos')return;const f=ensureFinance();if(f.legacyPayrollCleanupDone)return;const invalid=Object.entries(f.salaryPayments||{}).filter(([,p])=>!p.balanceDeltas&&!p.paymentAccount&&(!(p.scope||'')||p.scope===paymentScope()&&p.week>timelinePaymentWeek()));if(!invalid.length){f.legacyPayrollCleanupDone=true;return}const required=new Map();for(const [,p]of invalid)if(p.cashApplied)required.set(p.residentId,(required.get(p.residentId)||0)+Number(p.amount||0));if([...required].some(([id,amount])=>Number(data.inwoners.find(n=>n.id===id)?.cashGp||0)<amount))return;f.removedLegacyPayroll??=[];for(const [key,p]of invalid){f.removedLegacyPayroll.push({key,record:structuredClone(p),reason:'Foutieve oude periodetelling'});if(p.cashApplied){const employee=data.inwoners.find(n=>n.id===p.residentId);employee.cashGp=Number(employee.cashGp||0)-Number(p.amount||0)}if(p.ownerCashApplied){const owner=data.inwoners.find(n=>n.id===p.employerId);if(owner)owner.cashGp=Number(owner.cashGp||0)+Number(p.amount||0)}delete f.salaryPayments[key]}f.legacyPayrollCleanupDone=true;persist()}
function settleBankPayments(id,records){const resident=data.inwoners.find(n=>n.id===id);if(!resident)return {ok:false,message:'Inwoner niet gevonden.'};const deltas=new Map();for(const p of records){if(p.paid||p.cancelled)continue;const signed=p.direction==='inbound'?-Number(p.amount):Number(p.amount);deltas.set(id,(deltas.get(id)||0)+signed);if(p.lodgingDue&&p.innOwnerId)deltas.set(p.innOwnerId,(deltas.get(p.innOwnerId)||0)+Number(p.lodgingDue));}for(const [who,change]of deltas){const n=data.inwoners.find(n=>n.id===who);if(!n||Number(n.bankGp||0)+change<0)return {ok:false,message:'Onvoldoende banksaldo of ontbrekende ontvanger.'}}for(const p of records){if(p.paid||p.cancelled)continue;const ds=[{id,amount:p.direction==='inbound'?-Number(p.amount):Number(p.amount)}];if(p.lodgingDue&&p.innOwnerId)ds.push({id:p.innOwnerId,amount:Number(p.lodgingDue)});for(const d of ds){const n=data.inwoners.find(n=>n.id===d.id);n.bankGp=Number(n.bankGp||0)+d.amount}p.bankDeltas=ds;p.paid=true;p.received=true;p.paidDay=currentEffectiveDay()}return {ok:true}}
function reverseBankDeltas(deltas){const combined=new Map();for(const d of deltas)combined.set(d.id,(combined.get(d.id)||0)-d.amount);for(const [id,amount]of combined){const n=data.inwoners.find(n=>n.id===id);if(!n||Number(n.bankGp||0)+amount<0)return {ok:false,message:'Onvoldoende banksaldo om deze betaling terug te draaien.'}}for(const [id,amount]of combined){const n=data.inwoners.find(n=>n.id===id);n.bankGp=Number(n.bankGp||0)+amount}return {ok:true}}
function recordManualBalanceChanges(r,bank,cash){const f=ensureFinance();for(const [field,value,label]of [['bankGp',bank,'Bank'],['cashGp',cash,'Contant']]){const delta=Number(value)-Number(r[field]||0);if(Math.abs(delta)<.005)continue;(f.transactions??=[]).push({id:crypto.randomUUID(),residentId:r.id,label:(moneyReasonDraft?moneyReasonDraft+' — ':'')+label+' '+(delta>0?'toegevoegd':'afgenomen'),direction:delta>0?'ontvangen':'gedaan',amount:Math.abs(delta),week:Math.max(1,timelinePaymentWeek()),campaignDay:currentEffectiveDay(),balanceDeltas:[{id:r.id,field,amount:delta}]})}}

function historyFilterAndDelete(){const dialog=$('#entityDates');if(!dialog)return;const table=dialog.querySelector('table');const reset=document.createElement('button');reset.type='button';reset.textContent='Historie opnieuw beginnen';reset.className='history-reset-button';reset.onclick=openHistoryReset;dialog.querySelector('h2').after(reset);dialog.querySelector('h2').insertAdjacentHTML('afterend','<div class="history-filters"><label>Onderdeel<input id="historyPart" placeholder="Naam…"></label><label>Soort wijziging<input id="historyKind" placeholder="Eigenaar, woonplek, werkplek…"></label><label>Datum<input id="historyDate" placeholder="26 Flamerule…"></label></div>');table.tHead.rows[0].insertAdjacentHTML('beforeend','<th></th>');for(const row of table.tBodies[0].rows){const b=row.querySelector('[data-date-key]');if(!b)continue;row.insertAdjacentHTML('beforeend',`<td><button data-delete-history-key="${esc(b.dataset.dateKey)}" data-delete-history-index="${b.dataset.dateIndex}">Verwijderen</button></td>`)}for(const id of ['historyPart','historyKind','historyDate'])$('#'+id).oninput=()=>{for(const row of table.tBodies[0].rows)row.hidden=!row.cells[0].textContent.toLowerCase().includes($('#historyPart').value.toLowerCase())||!row.cells[2].textContent.toLowerCase().includes($('#historyKind').value.toLowerCase())||!row.cells[1].textContent.toLowerCase().includes($('#historyDate').value.toLowerCase())};dialog.querySelectorAll('[data-delete-history-key]').forEach(b=>b.onclick=()=>{if(!confirm('Historie-entry verwijderen? Dit wijzigt historische berekeningen, maar draait geen betaling of huidige gegevens terug.'))return;const key=b.dataset.deleteHistoryKey,index=Number(b.dataset.deleteHistoryIndex);const result=removeEntityHistoryEntry(key,index);if(!result.ok){toast(result.message);return}persist();openEntityDates()})}
function payoutDescription(id,p){const resident=data.inwoners.find(n=>n.id===id),names=data.locaties.filter(r=>r.ownerId===id).map(r=>r.name);return p.label||(p.direction==='inbound'?(p.lodgingDue?'Overnachtingen — '+lodgingName():'Onderhoud en kosten'):names.length?'Opbrengst — '+names.join(', '):'Opbrengst — '+(resident?.name||'inwoner'))}

function historyRowSortValue(row,index){if(index!==1)return row.cells[index].textContent.trim();const button=row.querySelector('[data-date-key]');return data.entityHistory[button.dataset.dateKey][Number(button.dataset.dateIndex)].day}
function enableHistorySorting(){const table=$('#entityDates table');if(!table)return;let active=-1,direction=1;const headers=[...table.tHead.rows[0].cells].slice(0,3),labels=headers.map(h=>h.textContent);headers.forEach((header,index)=>{const button=document.createElement('button');button.type='button';button.className='column-sort';button.textContent=labels[index]+' ↕';header.replaceChildren(button);button.onclick=()=>{direction=active===index?-direction:1;active=index;const rows=[...table.tBodies[0].rows];rows.sort((a,b)=>direction*compareFinanceValues(historyRowSortValue(a,index),historyRowSortValue(b,index)));rows.forEach(row=>table.tBodies[0].append(row));headers.forEach((h,i)=>{h.setAttribute('aria-sort',i===index?(direction===1?'ascending':'descending'):'none');h.firstChild.textContent=labels[i]+(i===index?(direction===1?' ↑':' ↓'):' ↕')})}})}
function townSettings(){if(!data.townSettings)data.townSettings={protectorId:'',lodgingId:data.locaties.find(r=>r.name.trim().toLowerCase()==='the crossroads rest')?.id||''};return data.townSettings}
function lodgingName(){return lodgingInn()?.name||'Geen overnachtingsgebouw ingesteld'}
function showTownSettings(){let section=$('#townSettings');if(!section){section=document.createElement('details');section.id='townSettings';document.querySelector('aside nav').after(section)}const settings=townSettings(),missing=!data.inwoners.some(n=>n.id===settings.protectorId)||!data.locaties.some(r=>r.id===settings.lodgingId);section.innerHTML=`<summary>Stadsinstellingen ${missing?'<span class="settings-warning" title="Instellingen ontbreken">●</span>':''}</summary><label>Lord Protector (Burgemeester)<select id="protectorChoice"><option value="">Kies een character</option>${data.inwoners.map(n=>`<option value="${esc(n.id)}" ${settings.protectorId===n.id?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label><label>Overnachtingsgebouw<select id="lodgingChoice"><option value="">Kies een gebouw</option>${data.locaties.map(r=>`<option value="${esc(r.id)}" ${settings.lodgingId===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><p>Overnachtingen worden betaald aan de eigenaar van dit gebouw.</p>`;section.hidden=player;$('#protectorChoice').onchange=e=>{settings.protectorId=e.target.value;persist();render()};$('#lodgingChoice').onchange=e=>{settings.lodgingId=e.target.value;persist();render()}}
function configureTownUi(){showTownSettings();$('#advance')?.remove();if(view==='finance'){const rate=$('[data-finance-tab="rates"]'),history=[...document.querySelectorAll('.finance-toolbar button')].find(b=>b.textContent==='Ingangsdatums & historie');if(rate&&history)history.before(rate)}if(view==='inwoners'){const id=townSettings().protectorId;const card=$('#content .card[data-id="'+CSS.escape(id)+'"]');card?.querySelector('h2')?.insertAdjacentHTML('afterend','<p class="protector-title">Lord Protector (Burgemeester)</p>')}polishAppUi();organizeChancellery()}
function bankTransfer(fromId,toId,amount,label){const from=data.inwoners.find(n=>n.id===fromId),to=data.inwoners.find(n=>n.id===toId);amount=Number(amount);if(!from||!to||from===to||!Number.isFinite(amount)||amount<=0)return {ok:false,message:'Kies twee verschillende inwoners en een geldig bedrag.'};if(Number(from.bankGp||0)<amount)return {ok:false,message:'Onvoldoende banksaldo bij de afzender.'};from.bankGp=Number(from.bankGp||0)-amount;to.bankGp=Number(to.bankGp||0)+amount;(ensureFinance().transactions??=[]).push({id:crypto.randomUUID(),residentId:fromId,toResidentId:toId,label:label||'Bankoverschrijving',direction:'gedaan',amount,week:Math.max(1,timelinePaymentWeek()),campaignDay:currentEffectiveDay(),bankDeltas:[{id:fromId,amount:-amount},{id:toId,amount}]});return {ok:true}}
function addBankTransferForm(){if(view!=='finance'||financeTab!=='payouts')return;const old=$('#residentTransaction');if(!old)return;const section=old.closest('section');section.querySelector('h2').textContent='Bankoverschrijving';const options=data.inwoners.map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('');old.innerHTML=`<label>Van<select name="fromId">${options}</select></label><label>Naar<select name="toId">${options}</select></label><label>Bedrag (gp)<input name="amount" type="number" min=".01" step=".01" required></label><label>Omschrijving<input name="label" maxlength="120" required></label><button class="primary">Overmaken</button>`;old.onsubmit=e=>{e.preventDefault();const form=new FormData(old),result=bankTransfer(form.get('fromId'),form.get('toId'),form.get('amount'),String(form.get('label')).trim());if(!result.ok){toast(result.message);return}persist();render()}}
function addReportPaymentRemoval(n){const report=$('#residentReport'),table=report.querySelectorAll('table')[2],entries=residentLedger(n.id);if(!table)return;table.tHead.rows[0].insertAdjacentHTML('beforeend','<th></th>');[...table.tBodies[0].rows].forEach((row,index)=>{const item=entries[index];if(!item)return;const button=document.createElement('button');button.textContent='Verwijderen';button.onclick=()=>{if(!confirm('Deze betalingsregel laten vervallen? Een uitgevoerde geldmutatie wordt teruggedraaid.'))return;const result=removeCashbookEntry(item.sourceKind,item.sourceKey);if(!result.ok){toast(result.message);return}if(item.sourceKind==='payout')ensureFinance().payouts[item.sourceKey].cancelled=true;if(item.sourceKind==='salary')ensureFinance().salaryPayments[item.sourceKey].cancelled=true;if(item.sourceKind==='purchase')ensureFinance().purchaseInvoices.find(p=>p.id===item.sourceKey).cancelled=true;persist();openResidentReport(n)};const cell=document.createElement('td');cell.append(button);row.append(cell)})}

function actionSvg(kind){const paths=kind==='trash'?'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>':kind==='crown'?'<path d="m3 6 5 5 4-8 4 8 5-5-2 14H5L3 6ZM5 16h14"/>':'<path d="m15 4 5 5M4 20l4-1L20 7a2 2 0 0 0-4-4L4 15v5Z"/>';return `<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths}</svg>`}
function polishActionIcons(root=document){const buttons=[...(root.querySelectorAll?.('button:not([data-action-icon])')||[])],parent=root.closest?.('button');if(parent&&!parent.dataset.actionIcon)buttons.push(parent);new Set(buttons).forEach(button=>{if(button.dataset.actionIcon)return;const text=button.textContent.trim(),remove=/^(Verwijderen|.* verwijderen)$/i.test(text),edit=/\b(bewerken|wijzigen)\b/i.test(text);if(!remove&&!edit)return;if(button.closest('nav')||button.dataset.financialAction)return;button.dataset.actionIcon=remove?'trash':'edit';button.classList.add('icon-action');button.setAttribute('aria-label',text);button.title=text;button.innerHTML=actionSvg(remove?'trash':'edit')})}
