function residentOpenAmounts(id){const f=ensureFinance(),items=[];for(const [key,p]of Object.entries(f.payouts||{})){if(p.cancelled||p.paid||!key.startsWith(paymentScope()))continue;const [period,...parts]=key.slice(paymentScope().length).split(':');if(parts.join(':')!==id||Number(period)>timelinePaymentWeek()||Number(p.amount)<=0)continue;items.push({label:payoutDescription(id,p),period:Number(period),direction:p.direction==='inbound'?'debt':'claim',amount:Number(p.amount)})}for(const p of Object.values(f.salaryPayments||{})){if(p.cancelled||p.ownerCashApplied||(p.scope||'')!==paymentScope()||p.week>timelinePaymentWeek()||Number(p.amount)<=0)continue;if(p.employerId===id)items.push({label:p.label+' → '+(data.inwoners.find(n=>n.id===p.residentId)?.name||'medewerker'),period:p.week,direction:'debt',amount:Number(p.amount)});if(p.residentId===id&&!p.cashApplied)items.push({label:p.label,period:p.week,direction:'claim',amount:Number(p.amount)})}return {debt:items.filter(p=>p.direction==='debt').reduce((a,p)=>a+p.amount,0),claim:items.filter(p=>p.direction==='claim').reduce((a,p)=>a+p.amount,0),items}}
