function addAutomaticResetControls(){if(view!=='finance'||financeTab!=='buildings')return;document.querySelectorAll('.building-table [data-asset][data-field$="Override"]').forEach(input=>{const id=input.dataset.asset,field=input.dataset.field,rule=ensureFinance().assets[id]||{};if(rule[field]===undefined)return;const button=document.createElement('button');button.type='button';button.className='automatic-reset';button.textContent='↺ Automatisch';button.setAttribute('aria-label','Automatische berekening herstellen — '+(data.locaties.find(r=>r.id===id)?.name||'pand'));button.onclick=()=>{resetAssetOverride(id,field);persist();render()};input.closest('td').append(button)})}
function renderCompactFinanceOverview(){if(view!=='finance'||financeTab!=='overview')return;const cards=$('#financeBody .cards');if(!cards)return;const ids=[...cards.querySelectorAll('[data-resident-id]')].map(card=>card.dataset.residentId),wrapper=document.createElement('div');wrapper.className='finance-table-wrap resident-status-table';wrapper.innerHTML=`<table class="finance-table"><thead><tr>${[['name','Inwoner'],['bank','Bank'],['assets','Panden'],['cells','Grond'],['wealth','Rijkdom'],['debt','Te betalen'],['claim','Te ontvangen']].map(([key,label])=>`<th><button class="column-sort" data-status-sort="${key}">${label} ↕</button></th>`).join('')}<th>Spelersoverzicht</th></tr></thead><tbody>${ids.map(id=>{const n=data.inwoners.find(n=>n.id===id),s=residentWealth(n),open=residentOpenAmounts(id);return `<tr data-status-resident="${esc(id)}"><td><b>${esc(n.name)}</b>${n.npc?'<small>NPC</small>':''}</td><td>${gp(s.bank)}</td><td>${s.assets.length}<small>${gp(s.value-s.plotCost)}</small></td><td>${s.plots.length} ${s.plots.length===1?'perceel':'percelen'}<small>${s.cells} vakjes · ${gp(s.plotCost)}</small></td><td>${gp(s.wealth)}</td><td class="${open.debt?'amount-due':''}">${gp(open.debt)}</td><td>${gp(open.claim)}</td><td><button data-open-player-report="${esc(id)}">Bekijken / exporteren</button></td></tr>`}).join('')}</tbody></table>`;cards.replaceWith(wrapper);wrapper.querySelectorAll('[data-open-player-report]').forEach(b=>b.onclick=()=>openResidentReport(data.inwoners.find(n=>n.id===b.dataset.openPlayerReport)));let active='',direction=1;wrapper.querySelectorAll('[data-status-sort]').forEach(b=>b.onclick=()=>{const key=b.dataset.statusSort;direction=active===key?-direction:1;active=key;const value=id=>{const n=data.inwoners.find(n=>n.id===id),s=residentWealth(n);return key==='name'?n.name:key==='assets'?s.assets.length:['debt','claim'].includes(key)?residentOpenAmounts(id)[key]:s[key]};[...wrapper.querySelectorAll('tbody tr')].sort((a,b)=>direction*compareFinanceValues(value(a.dataset.statusResident),value(b.dataset.statusResident))).forEach(row=>wrapper.querySelector('tbody').append(row));wrapper.querySelectorAll('[data-status-sort]').forEach(button=>{button.textContent=button.textContent.replace(/[↕↑↓]/g,'').trim()+' '+(button===b?(direction===1?'↑':'↓'):'↕');button.closest('th').setAttribute('aria-sort',button===b?(direction===1?'ascending':'descending'):'none')})})}
function addResidentStatusSummary(n){const s=residentWealth(n),open=residentOpenAmounts(n.id),report=$('#residentReport .resident-report-html');if(!report)return;report.insertAdjacentHTML('afterbegin','<p class="report-asof">Stand: '+esc(calendarLabel(currentEffectiveDay()))+'</p>');report.querySelector('.report-summary').insertAdjacentHTML('afterend',`<div class="status-summary"><div><small>Openstaand te betalen</small><b class="${open.debt?'amount-due':''}">${gp(open.debt)}</b></div><div><small>Nog te ontvangen</small><b>${gp(open.claim)}</b></div><div><small>Panden</small><b>${s.assets.length}</b></div><div><small>Grond</small><b>${s.plots.length} ${s.plots.length===1?'perceel':'percelen'} · ${s.cells} vakjes</b></div></div><section class="open-obligations"><h3>Openstaande bedragen</h3>${open.items.length?`<ul>${open.items.map(p=>`<li><b>${p.direction==='debt'?'Te betalen':'Te ontvangen'}: ${gp(p.amount)}</b> — ${esc(p.label)} · periode ${p.period}</li>`).join('')}</ul>`:'<p>Geen openstaande bedragen.</p>'}</section>`);const mdButton=$('#downloadResidentReport'),htmlButton=document.createElement('button');htmlButton.type='button';htmlButton.textContent='↓ Spelersoverzicht HTML';htmlButton.onclick=()=>{const clone=report.cloneNode(true);clone.querySelectorAll('button,.stat-breakdown').forEach(el=>el.remove());const html='<!doctype html><html lang="nl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(n.name)+' — status</title><style>body{max-width:950px;margin:32px auto;padding:0 24px;font:14px/1.6 system-ui;color:#293c35}h1,h2,h3{font-family:Georgia}table{width:100%;border-collapse:collapse;margin:12px 0}td,th{text-align:left;padding:10px;border:1px solid #ddd}th{background:#edf0e7}.report-summary,.status-summary{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:16px 0}.report-summary>div,.status-summary>div{border:1px solid #ddd;padding:12px}small,b{display:block}.amount-due{color:#9b4532}.finance-table-wrap{overflow:auto}@media print{body{margin:0;max-width:none}table{font-size:11px}tr{break-inside:avoid}}</style><h1>'+esc(n.name)+' — '+esc(data.villageName)+'</h1><p>Stand: '+esc(calendarLabel(currentEffectiveDay()))+'</p>'+clone.outerHTML+'</html>';downloadData(html,'spelersoverzicht-'+n.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.html','text/html;charset=utf-8')};mdButton.after(htmlButton)}
