function shiftCellKey(key,left,top){const [x,y]=key.split(',').map(Number);return (x+left)+','+(y+top)}
function translateMapRecord(r,type,left,top,oldCols,oldRows,newCols,newRows){if(type==='plots'){assignPlotCells(r,plotCells(r).map(([x,y])=>[x+left,y+top]));return}if(r.footprint){r.footprint.col+=left;r.footprint.row+=top}if(Number.isFinite(r.x))r.x=(r.x/100*oldCols+left)/newCols*100;if(Number.isFinite(r.y))r.y=(r.y/100*oldRows+top)/newRows*100}
function growMapEdges({left=0,top=0,right=0,bottom=0}){if(!data.map||![left,top,right,bottom].every(n=>Number.isInteger(n)&&n>=0))return {ok:false,message:'Gebruik hele aantallen van nul of hoger.'};const m=data.map,oldCols=m.cols,oldRows=m.rows,cols=oldCols+left+right,rows=oldRows+top+bottom;if(cols>100||rows>100)return {ok:false,message:'De kaart kan maximaal 100 × 100 vakjes groot zijn.'};if(!(left+top+right+bottom))return {ok:false,message:'Vul in aan welke kant je vakjes wilt toevoegen.'};m.cells=Object.fromEntries(Object.entries(m.cells).map(([key,v])=>[shiftCellKey(key,left,top),v]));m.vertical=(m.vertical||[]).map(key=>shiftCellKey(key,left,top));for(const layer of Object.values(m.layers||{})){layer.tiles=(layer.tiles||[]).map(key=>shiftCellKey(key,left,top));for(const op of layer.ops||[])op.points=op.points.map(([x,y])=>[x+left*32,y+top*32])}for(const tree of m.trees||[]){tree.x+=left*32;tree.y+=top*32}for(const p of m.plots||[])translateMapRecord(p,'plots',left,top,oldCols,oldRows,cols,rows);for(const r of data.locaties)translateMapRecord(r,'locaties',left,top,oldCols,oldRows,cols,rows);for(const [key,entries]of Object.entries(data.entityHistory||{})){const type=key.split(':')[0];if(type==='plots'||type==='locaties')for(const entry of entries)translateMapRecord(entry.state,type,left,top,oldCols,oldRows,cols,rows)}for(const group of ['entityHistoryBaselines','entityHistoryCaptureStates'])for(const [key,entry]of Object.entries(data[group]||{})){const type=key.split(':')[0];if(type==='plots'||type==='locaties')translateMapRecord(entry.state,type,left,top,oldCols,oldRows,cols,rows)}if(m.reference){m.reference.width??=oldCols*32;m.reference.height??=oldRows*32;m.reference.x=(m.reference.x||0)+left*32;m.reference.y=(m.reference.y||0)+top*32}buildingDraft=buildingDraft.map(([x,y])=>[x+left,y+top]);plotDraft=plotDraft.map(([x,y])=>[x+left,y+top]);m.cols=cols;m.rows=rows;mapCamera=null;mapCameraSize='';return {ok:true}}
function appendMapGrowth(){if(view!=='kaart'||player||toolSection!=='settings')return;const dock=$('.tool-popover');if(!dock||$('#growMapForm'))return;const form=document.createElement('form');form.id='growMapForm';form.innerHTML='<h3>Kaart uitbreiden</h3><div class="grow-map-fields">'+[['top','Boven'],['left','Links'],['right','Rechts'],['bottom','Onder']].map(([key,label])=>`<label>${label}<input type="number" name="${key}" min="0" max="95" step="1" value="0" required></label>`).join('')+'</div><button class="primary">Vakjes toevoegen</button>';form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),edges=Object.fromEntries(['left','top','right','bottom'].map(k=>[k,Number(f.get(k))]));if(data.map.cols+edges.left+edges.right>100||data.map.rows+edges.top+edges.bottom>100){toast('Maximaal 100 × 100 vakjes.');return}if(!Object.values(edges).some(Boolean))return;remember();const result=growMapEdges(edges);if(!result.ok){undoMaps.pop();toast(result.message);return}persist();render();toast('Kaart uitgebreid; bestaande plekken zijn behouden.')};dock.append(form)}
