function goToMapEntity(type,id){if(!data.map){toast('Maak eerst een stadskaart.');return}const r=type==='plots'?data.map.plots.find(p=>p.id===id):data.locaties.find(r=>r.id===id);if(!r)return;let x,y,w,h;if(type==='plots'){const cells=plotCells(r),xs=cells.map(c=>c[0]),ys=cells.map(c=>c[1]);x=Math.min(...xs)*32;y=Math.min(...ys)*32;w=(Math.max(...xs)-Math.min(...xs)+1)*32;h=(Math.max(...ys)-Math.min(...ys)+1)*32}else if(r.footprint){x=r.footprint.col*32;y=r.footprint.row*32;w=r.footprint.w*32;h=r.footprint.h*32}else{x=r.x/100*mapWidth();y=r.y/100*mapHeight();w=h=32}const width=mapWidth(),height=mapHeight(),cw=Math.min(width,Math.max(width/8,w*3,h*3*width/height)),ch=cw*height/width;mapCamera=boundMapCamera({x:x+w/2-cw/2,y:y+h/2-ch/2,w:cw,h:ch},width,height);mapCameraSize=width+':'+height;focusedMapEntity={type,id};if(type!=='plots')selected=id;view='kaart';drawing=false;place=null;toolSection=null;render();window.scrollTo({top:0,behavior:'smooth'})}
