function simplifyMapTools(){if(view!=='kaart'||player)return;const panel=$('.rail-editor');if(!panel)return;panel.classList.add('labeled-tools');const labels={select:'Selecteren',terrain:'Terrein',build:'Pand',settings:'Kaart uitbreiden',reference:'Voorbeeld',display:'Weergave / export'};panel.querySelectorAll('.tool-rail [data-section]').forEach(b=>{const section=b.dataset.section,span=document.createElement('span');span.className='tool-name';span.textContent=labels[section];b.append(span);if(section==='build')b.onclick=()=>{if(!data.map)beginMap();brush='house';drawing=true;toolSection='build';render()}});const building=panel.querySelector('[data-section="build"]');if(building){const plot=document.createElement('button');plot.type='button';plot.className=brush==='plot'&&drawing?'active':'';plot.innerHTML='▧ <span class="tool-name">Perceel</span>';plot.setAttribute('aria-label','Perceel tekenen');plot.onclick=()=>{if(!data.map)beginMap();brush='plot';drawing=true;toolSection='build';render()};building.after(plot)}for(const [id,label]of [['railUndo','Ongedaan'],['railRedo','Opnieuw']]){const b=$('#'+id);if(b)b.insertAdjacentHTML('beforeend',`<span class="tool-name">${label}</span>`)}const dock=$('.tool-popover');if(dock){dock.querySelectorAll('.paint-hint,.building-options p').forEach(p=>p.remove());const status=document.createElement('p');status.className='tool-instruction';status.textContent=toolSection==='build'?(brush==='plot'?'Teken vakjes voor een perceel. Bewaar het daarna.':'Teken je pand. Bewaar het en geef het een naam.'):toolSection==='terrain'?'Kies het terrein en Tekenen of Wissen. Sleep daarna op de kaart.':'';if(status.textContent)dock.append(status)}appendMapGrowth()}

