function humanPaymentPeriod(raw){const text=String(raw),match=text.match(/^harptos-(\d+)-([^|]+)\|(\d+)$/);if(!match)return text;const start=(Number(match[1])-1)*12+harptosMonths.indexOf(match[2]),period=Number(match[3]),position=start+Math.floor((period-1)/3);return `${(period-1)%3+1}e tenday · ${harptosMonths[position%12]} ${Math.floor(position/12)+1}`}
