let salaryAccountChoices={};
function salaryPaymentCheck(p,account='bank'){if(account!=='bank')return {ok:false,message:'Salarisbetalingen verlopen via de bank.'};if(!p||p.ownerCashApplied||p.cancelled)return {ok:false,message:'Deze salarisbetaling is al verwerkt of vervallen.'};const employee=data.inwoners.find(n=>n.id===p.residentId),owner=data.inwoners.find(n=>n.id===p.employerId),amount=Number(p.amount);if(!employee||!owner||employee.id===owner.id)return {ok:false,message:'Controleer de eigenaar en medewerker.'};if(!Number.isFinite(amount)||amount<0)return {ok:false,message:'Ongeldig salarisbedrag.'};return {ok:true,employee,owner,amount,field:account==='bank'?'bankGp':'cashGp'}}
function settleSalary(p,account='bank'){const check=salaryPaymentCheck(p,account);if(!check.ok)return check;const {employee,owner,amount,field}=check;if(Number(owner[field]||0)<amount)return {ok:false,message:'De eigenaar heeft onvoldoende '+(account==='bank'?'banksaldo':'contant geld')+'. Stort eerst geld of vul het banksaldo aan.'};const deltas=[{id:owner.id,field,amount:-amount}];if(!p.cashApplied)deltas.push({id:employee.id,field,amount});else deltas.push({id:employee.id,field:'cashGp',amount,previouslyApplied:true});for(const d of deltas)if(!d.previouslyApplied){const n=data.inwoners.find(n=>n.id===d.id);n[d.field]=Number(n[d.field]||0)+d.amount}p.balanceDeltas=deltas;p.paymentAccount=account;p.ownerCashApplied=true;p.cashApplied=account==='cash';p.paid=true;p.paidDay=currentEffectiveDay();return {ok:true}}
function payEmployerSalaries(group,account='bank'){if(!group?.records?.length)return {ok:false,message:'Geen openstaande salarissen.'};const checks=group.records.map(p=>salaryPaymentCheck(p,account)),bad=checks.find(c=>!c.ok);if(bad)return bad;if(new Set(group.records).size!==group.records.length||checks.some(c=>c.owner.id!==group.id))return {ok:false,message:'Controleer de salarisbetalingen.'};const owner=checks[0].owner,field=checks[0].field,total=checks.reduce((sum,c)=>sum+c.amount,0);if(Number(owner[field]||0)<total)return {ok:false,message:'Voor '+gp(total)+' salaris is onvoldoende '+(account==='bank'?'banksaldo':'contant geld')+' beschikbaar ('+gp(Number(owner[field]||0))+'). Stort eerst geld of vul het banksaldo aan.'};for(const p of group.records)settleSalary(p,account);return {ok:true}}
function configureSalaryAccountChoices(){if(view!=='finance'||financeTab!=='payouts')return;document.querySelectorAll('[data-owner-salary]').forEach(button=>{button.onclick=()=>openSalaryPaymentDialog(button.dataset.ownerSalary)})}
function openSalaryPaymentDialog(id){const owner=data.inwoners.find(n=>n.id===id),group=employerSalaryGroups().find(g=>g.id===id);if(!owner||!group)return;let dialog=$('#salaryPaymentDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='salaryPaymentDialog';document.body.append(dialog)}dialog.innerHTML=`<form><h2>Salaris betalen</h2><p>Eigenaar: <b>${esc(owner.name)}</b></p><p class="salary-total">Totaal: <b>${gp(group.amount)}</b></p><p class="finance-note">Voor ${[...new Set(group.records.map(p=>data.inwoners.find(n=>n.id===p.residentId)?.name||'Onbekend'))].map(esc).join(', ')} · ${group.records.length} salarisbetaling${group.records.length===1?'':'en'}.</p><label>Betalen via<select name="account"><option value="bank">Bank — ${gp(Number(owner.bankGp||0))} beschikbaar</option></select></label><p>Het bedrag gaat van de bankrekening van de eigenaar naar de bankrekening van de medewerker.</p><p class="salary-dialog-error" role="alert" hidden></p><div class="form-actions"><button type="button" data-salary-cancel>Annuleren</button><button class="primary">Betaling bevestigen</button></div></form>`;const form=dialog.querySelector('form'),account=form.elements.account;account.value='bank';account.onchange=()=>{salaryAccountChoices[id]=account.value;dialog.querySelector('[role="alert"]').hidden=true};dialog.querySelector('[data-salary-cancel]').onclick=()=>dialog.close();form.onsubmit=e=>{e.preventDefault();const current=employerSalaryGroups().find(g=>g.id===id);if(!current){dialog.close();render();toast('Er zijn geen openstaande salarissen meer.');return}const result=payEmployerSalaries(current,account.value);if(!result.ok){const error=dialog.querySelector('[role="alert"]');error.hidden=false;error.textContent=result.message;return}salaryAccountChoices[id]=account.value;dialog.close();persist();render();toast('Salaris '+(account.value==='bank'?'via bank':'contant')+' overgemaakt naar de medewerkers.')};dialog.showModal()}

let moneyManagerResident='';
function financeMoneyMutation(id,operation,options={}){const n=data.inwoners.find(n=>n.id===id);if(!n)return {ok:false,message:'Kies een inwoner.'};const current=Number(n.bankGp||0),round=v=>Math.round(Number(v)*100)/100;let amount=round(options.amount),delta,label=String(options.description||'').trim();if(!Number.isFinite(current)||current<0)return {ok:false,message:'Controleer het banksaldo.'};if(operation==='correct'){const target=round(options.bank);if(!Number.isFinite(target)||target<0||!label)return {ok:false,message:'Vul een geldig banksaldo en een omschrijving in.'};delta=round(target-current);label='Banksaldo corrigeren — '+label}else{if(!Number.isFinite(amount)||amount<=0)return {ok:false,message:'Vul een bedrag groter dan nul in.'};if(!['deposit','withdraw','add','subtract'].includes(operation))return {ok:false,message:'Kies een geldige handeling.'};if(['add','subtract'].includes(operation)&&(!label||options.account&&options.account!=='bankGp'))return {ok:false,message:'Gebruik de bankrekening en vul een omschrijving in.'};delta=['deposit','add'].includes(operation)?amount:-amount;label=({deposit:'Geld gestort op bank',withdraw:'Geld opgenomen van bank',add:'Bank bijgeschreven',subtract:'Bank afgeboekt'})[operation]+(label?' — '+label:'')}if(!delta)return {ok:false,message:'Het banksaldo is niet gewijzigd.'};if(round(current+delta)<0)return {ok:false,message:'Onvoldoende banksaldo. Er is niets verwerkt.'};const record={id:crypto.randomUUID(),residentId:id,label,direction:delta<0?'gedaan':'ontvangen',amount:Math.abs(delta),week:Math.max(1,timelinePaymentWeek()),campaignDay:currentEffectiveDay(),moneyOperation:operation,balanceDeltas:[{id,field:'bankGp',amount:delta}]};n.bankGp=round(current+delta);(ensureFinance().transactions??=[]).push(record);return {ok:true}}
function renderMoneyManager(){if(view!=='finance'||financeTab!=='payouts'||player)return;$('#moneyManager')?.remove();const section=document.createElement('section');section.id='moneyManager';section.innerHTML=`<h2>Bankbeheer</h2><p class="finance-note">Storten verhoogt het banksaldo; opnemen verlaagt het. Contant geld wordt buiten deze app bijgehouden. Alle bankmutaties staan in het kasboek.</p><form class="money-manager-form"><label>Inwoner<select name="resident" required>${data.inwoners.map(n=>`<option value="${esc(n.id)}">${esc(n.name)}${n.npc?' (NPC)':''}</option>`).join('')}</select></label><label>Handeling<select name="operation"><option value="deposit">Storten op bank</option><option value="withdraw">Opnemen van bank</option><option value="add">Bank bijschrijven</option><option value="subtract">Bank afboeken</option><option value="correct">Banksaldo corrigeren</option></select></label><label>Bank (gp)<input name="bank" type="number" min="0" step=".01" readonly></label><label data-money-amount>Bedrag (gp)<input name="amount" type="number" min=".01" step=".01" required></label><label class="money-description">Omschrijving<input name="description" maxlength="120" placeholder="Bijvoorbeeld storting, aankoop of correctie"></label><p class="money-operation-help"></p><button class="primary">Storten</button></form>`;$('#financeBody').append(section);const form=section.querySelector('form'),fields=form.elements;fields.resident.value=data.inwoners.some(n=>n.id===(financeOwner==='all'?moneyManagerResident:financeOwner))?(financeOwner==='all'?moneyManagerResident:financeOwner):(data.inwoners[0]?.id||'');const load=()=>{moneyManagerResident=fields.resident.value;fields.bank.value=Number(data.inwoners.find(n=>n.id===fields.resident.value)?.bankGp||0)};const configure=()=>{const mode=fields.operation.value,correct=mode==='correct';fields.amount.closest('label').hidden=correct;fields.amount.disabled=correct;fields.amount.required=!correct;fields.bank.readOnly=!correct;fields.description.required=['correct','add','subtract'].includes(mode);section.querySelector('button').textContent={deposit:'Storten',withdraw:'Opnemen',add:'Bijschrijven',subtract:'Afboeken',correct:'Correctie bewaren'}[mode];section.querySelector('.money-operation-help').textContent=correct?'Vul het juiste banksaldo in en licht het verschil toe.':mode==='deposit'?'Het gestorte bedrag wordt bijgeschreven op de bankrekening.':mode==='withdraw'?'Het opgenomen bedrag wordt afgeschreven van de bankrekening.':'Deze bankmutatie wordt opgenomen in het kasboek.';load()};fields.resident.onchange=load;fields.operation.onchange=configure;configure();form.onsubmit=e=>{e.preventDefault();const result=financeMoneyMutation(fields.resident.value,fields.operation.value,{amount:fields.amount.value,account:'bankGp',bank:fields.bank.value,description:fields.description.value});if(!result.ok){toast(result.message);return}persist();render();toast('Bankmutatie verwerkt en opgenomen in het kasboek.')}}

