function prepareDatedRelations(){if(!relationChanges())return true;if(relationApprovedDay!==null){entityCaptureDay=relationApprovedDay;relationApprovedDay=null;return true}let dialog=$('#relationDateDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='relationDateDialog';document.body.append(dialog)}const config=calendarConfig();dialog.innerHTML=`<form><h2>Ingangsdatum kiezen</h2><p>Vanaf wanneer gelden deze wijzigingen in woonplek, werkplek, eigendom of persoonlijk salaris?</p>${dateFields('relationEffective',campaignDate(currentEffectiveDay()),config.system)}<p class="field-help">De wijziging wordt opgenomen in Ingangsdatums & historie. Kies een datum tussen de eerste campagnedag en de huidige tijdlijndatum.</p><p role="alert" hidden></p><div class="form-actions"><button type="button" data-cancel-relation>Terug</button><button class="primary">Datum toepassen en bewaren</button></div></form>`;bindDateFields('relationEffective');dialog.querySelector('[data-cancel-relation]').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{const date=readDateFields('relationEffective',config.system),day=config.system==='gregorian'?Math.round((Date.parse(date)-Date.parse(config.gregorianStart))/86400000)+1:harptosOrdinal(date)-harptosOrdinal(config.harptosStart)+1;if(!Number.isInteger(day)||day<1||day>currentEffectiveDay())throw Error();relationApprovedDay=day;dialog.close();$('#form').requestSubmit()}catch{const error=dialog.querySelector('[role="alert"]');error.hidden=false;error.textContent='Kies een geldige datum binnen de campagne.'}};dialog.showModal();return false}
function saveResidentWorkplace(r,value){const next=String(value||'');if(r.workplace!==next){for(const [id,rule]of Object.entries(ensureFinance().assets))if(rule.staffResidentId===r.id&&id!==next){rule.staffResidentId='';rule.staff='none'}}r.workplace=next}
function timelineTownMetrics(){const events=new Map();for(const event of data.tijdlijn){const day=Number(event.day);if(!Number.isInteger(day)||day<=0)continue;if(!events.has(day))events.set(day,[]);events.get(day).push(event.name)}return [...events.keys()].sort((a,b)=>a-b).map(day=>({...withDatedState(day,()=>currentTownMetrics()),day,eventNames:events.get(day).join(' · ')}))}
