function profileOwnerWorkAllowed(profile){return profile.ownerCanWork===undefined?!!financeDefaults.catalog.find(p=>p.id===profile.id)?.workshop:!!profile.ownerCanWork}
const renderFinance136=renderFinance;
renderFinance=function(){const page=chancelleryPage;financeTab=['deeds','vital','marriages'].includes(page)?'registry':page;renderFinance136();if(['deeds','vital','marriages'].includes(page)){civilFilters.type=page==='deeds'?'ownership':page==='marriages'?'marriage':(['birth','death'].includes(civilFilters.type)?civilFilters.type:'birth');renderCivilRegistry();const allowed=page==='deeds'?['ownership']:page==='marriages'?['marriage']:['birth','death'];for(const id of ['civilNewType','civilTypeFilter']){const select=$('#'+id);for(const option of [...select.options])if(!allowed.includes(option.value))option.remove();select.value=civilFilters.type;}}if(['owners','values','residents','transfers','appointments'].includes(page))renderChancelleryPage(page);};
organizeChancellery=function(){if(view!=='finance')return;const toolbar=$('.finance-toolbar');if(!toolbar)return;let themes=$('#chancelleryThemes');if(!themes){themes=document.createElement('div');themes.id='chancelleryThemes';themes.className='chancellery-themes';themes.setAttribute('role','tablist');themes.setAttribute('aria-label','Thema’s Kanselarij');$('#stats').before(themes)}themes.innerHTML=Object.entries(chancelleryThemes).map(([id,t])=>`<button role="tab" aria-selected="${id===chancelleryTheme}" class="${id===chancelleryTheme?'primary':''}" data-theme="${id}">${t.label}</button>`).join('');themes.querySelectorAll('button').forEach(b=>b.onclick=()=>{chancelleryTheme=b.dataset.theme;chancelleryPage=chancelleryThemes[chancelleryTheme].pages[0][0];civilFilters.type='all';render()});const label=$('#financeOwner')?.closest('label'),actions=toolbar.querySelector('.finance-actions')||document.createElement('div');actions.className='finance-actions';actions.querySelector('[data-finance-tab="rates"]')?.remove();const tabs=document.createElement('div');tabs.className='chancellery-sections';tabs.setAttribute('aria-label','Onderdelen '+chancelleryThemes[chancelleryTheme].label);tabs.innerHTML=chancelleryThemes[chancelleryTheme].pages.map(([id,title])=>`<button data-section="${id}" aria-current="${chancelleryPage===id?'page':'false'}" class="${chancelleryPage===id?'primary':''}">${title}</button>`).join('');tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{chancelleryPage=b.dataset.section;civilFilters.type='all';render()});toolbar.replaceChildren(tabs,actions);toolbar.classList.add('chancellery-toolbar');if(label){const filters=document.createElement('div');filters.className='chancellery-filter';filters.append(label);toolbar.append(filters)}if(chancelleryTheme==='property')$('#subtitle').textContent='Grond, gebouwen, eigenaren en geregistreerd bezit.';if(chancelleryTheme==='civil')$('#subtitle').textContent='Inwoners, registraties en officiële documenten.';if(chancelleryPage==='buildings')addPropertyDateColumns();if(chancelleryPage==='rates')addOwnerWorkRates();if(chancelleryPage==='buildings')document.querySelectorAll('.owner-help-cell input').forEach(input=>{const r=data.locaties.find(r=>r.id===input.dataset.asset);if(r&&!profileOwnerWorkAllowed(assetFinance(r).profile))input.parentElement.textContent='Niet van toepassing'});};
function addPropertyDateColumns(){for(const [selector,type]of [['[data-asset-owner]','locaties'],['[data-plot-owner]','plots']]){const inputs=[...$('#financeBody').querySelectorAll(selector)];if(!inputs.length)continue;const table=inputs[0].closest('table');if(table.dataset.creationDates)continue;table.dataset.creationDates='true';table.tHead.rows[0].insertAdjacentHTML('beforeend','<th>Aanmaakdatum & historie</th>');inputs.forEach(input=>{const id=input.dataset.assetOwner||input.dataset.plotOwner;const cell=input.closest('tr').insertCell();const button=document.createElement('button');button.textContent=entityCreationLabel(type,id);button.onclick=()=>openEntityDates(type+':'+id);cell.append(button)})}}
function addOwnerWorkRates(){const table=$('#financeBody table');if(!table||table.dataset.ownerEligibility)return;table.dataset.ownerEligibility='true';table.tHead.rows[0].insertAdjacentHTML('beforeend','<th>Eigenaar kan meewerken</th>');for(const row of table.tBodies[0].rows){const id=row.querySelector('[data-rate]')?.dataset.rate,p=ensureFinance().catalog.find(p=>p.id===id);if(!p)continue;const cell=row.insertCell(),input=document.createElement('input');input.type='checkbox';input.checked=profileOwnerWorkAllowed(p);input.setAttribute('aria-label','Eigenaar kan meewerken — '+p.name);input.onchange=()=>{p.ownerCanWork=input.checked;persist();render()};cell.append(input)}}
const decorateEntityCards136=decorateEntityCards;
decorateEntityCards=function(){decorateEntityCards136();if(view!=='locaties')return;document.querySelectorAll('#content .entity-card').forEach(card=>{if(card.querySelector('[data-building-dates]'))return;const id=card.dataset.id,button=document.createElement('button');button.type='button';button.dataset.buildingDates=id;button.textContent='Aanmaakdatum & historie';button.onclick=e=>{e.stopPropagation();openEntityDates('locaties:'+id)};card.append(button)})};
function chancelleryRows(headers,rows){return `<div class="finance-table-wrap"><table class="finance-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">Nog geen registraties.</td></tr>`}</tbody></table></div>`}
function renderChancelleryPage(page){const body=$('#financeBody'),people=data.inwoners.filter(n=>financeOwner==='all'||n.id===financeOwner);if(page==='owners'||page==='values'){body.innerHTML=`<h2>${page==='owners'?'Eigenaren':'Waardeoverzicht'}</h2>`+chancelleryRows(['Eigenaar','Panden','Percelen','Pandwaarde','Grondwaarde','Totale waarde'],people.map(n=>{const f=residentFinance(n.id);return `<tr><td>${esc(n.name)}</td><td>${f.assets.map(r=>esc(r.name)).join('<br>')||'—'}</td><td>${f.plots.map(p=>esc(plotLabel(p))).join('<br>')||'—'}</td><td>${gp(f.build)}</td><td>${gp(f.plotCost)}</td><td>${gp(f.value)}</td></tr>`}));const unowned=civilProperties().filter(p=>!(p.type==='Pand'?data.locaties:data.map?.plots||[]).find(r=>r.id===p.id)?.ownerId);if(unowned.length)body.insertAdjacentHTML('beforeend',`<h3>Zonder toegewezen eigenaar</h3><p>${unowned.map(p=>esc(p.name)).join(', ')}</p>`);return}if(page==='residents'){body.innerHTML='<h2>Inwonersregister</h2>'+chancelleryRows(['Naam','Soort','Woonplek','Werkplek','Huwelijk','Registratie'],people.map(n=>`<tr><td><button data-resident-edit="${esc(n.id)}">${esc(n.name)}</button></td><td>${n.npc?'NPC':'PC'}</td><td>${esc(data.locaties.find(r=>r.id===n.location)?.name||'Geen vaste woonplek')}</td><td>${esc(data.locaties.find(r=>r.id===n.workplace)?.name||(n.workplace==='__travel__'?'Op reis':'—'))}</td><td>${esc(civilMarriageText(n.id)||'—')}</td><td>${esc(entityCreationLabel('inwoners',n.id))}</td></tr>`));body.querySelectorAll('[data-resident-edit]').forEach(b=>b.onclick=()=>edit('inwoners',b.dataset.residentEdit));return}const transfer=page==='transfers';body.innerHTML=`<h2>${transfer?'Eigendomsoverdracht':'Benoemingen'}</h2><p>${transfer?'Registreer een verkoop, schenking of erfenis. De gekozen ingangsdatum wordt in de eigendomshistorie vastgelegd. Een betaling boek je apart bij Betalingen; een eigendomsakte maak je bij Eigendomsakten.':'Leg functies en aanstellingen vast met een ingangsdatum. De Lord Protector wordt gekozen bij Stadsinstellingen.'}</p><button id="newDatedRegistration" class="primary">+ ${transfer?'Overdracht registreren':'Benoeming registreren'}</button>`;const records=transfer?(data.propertyTransfers||[]):(data.appointments||[]);body.insertAdjacentHTML('beforeend',chancelleryRows(transfer?['Datum','Eigendom','Van','Naar','Soort']:['Datum','Persoon','Functie','Toelichting'],records.filter(r=>financeOwner==='all'||r.personId===financeOwner||r.fromId===financeOwner||r.toId===financeOwner).slice().sort((a,b)=>b.day-a.day).map(r=>transfer?`<tr><td>${esc(calendarLabel(r.day))}</td><td>${esc(r.propertyName)}</td><td>${esc(r.fromName||'Geen eigenaar')}</td><td>${esc(r.toName)}</td><td>${esc(r.kind)}</td></tr>`:`<tr><td>${esc(calendarLabel(r.day))}</td><td>${esc(r.personName)}</td><td>${esc(r.title)}</td><td>${esc(r.notes)}</td></tr>`)));$('#newDatedRegistration').onclick=()=>openDatedRegistration(transfer)}
function registerPropertyTransfer(key,toId,kind,day){if(!Number.isInteger(day)||day<1||day>currentEffectiveDay())throw Error('Kies een datum binnen de campagne.');const [type,id]=key.split(':'),property=(type==='locaties'?data.locaties:type==='plots'?data.map?.plots||[]:[]).find(p=>p.id===id),owner=data.inwoners.find(n=>n.id===toId);if(!property||!owner)throw Error('Kies een eigendom en een nieuwe eigenaar.');if(property.ownerId===toId)throw Error('Deze persoon is al eigenaar.');if(!['Verkoop','Schenking','Erfenis'].includes(kind))throw Error('Kies een geldige overdracht.');captureEntityDates();const record={id:crypto.randomUUID(),propertyKey:key,propertyName:property.name||plotLabel(property),fromId:property.ownerId||'',fromName:data.inwoners.find(n=>n.id===property.ownerId)?.name||'',toId,toName:owner.name,kind,day};entityCaptureDay=day;property.ownerId=toId;(data.propertyTransfers??=[]).push(record);persist();return record}
function openDatedRegistration(transfer){let dialog=$('#datedRegistration');if(!dialog){dialog=document.createElement('dialog');dialog.id='datedRegistration';document.body.append(dialog)}const system=calendarConfig().system;dialog.innerHTML=`<form><h2>${transfer?'Eigendomsoverdracht':'Benoeming'}</h2>${transfer?`<label>Eigendom<select name="property" required>${civilProperties().map(p=>`<option value="${esc(p.key)}">${esc(p.type+' · '+p.name+' · '+p.owner)}</option>`).join('')}</select></label><label>Nieuwe eigenaar<select name="person" required>${ownerOptions('','Kies een inwoner')}</select></label><label>Soort<select name="kind"><option>Verkoop</option><option>Schenking</option><option>Erfenis</option></select></label>`:`<label>Inwoner<select name="person"><option value="">Persoon van buiten de stad</option>${data.inwoners.map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('')}</select></label><label>Naam (bij persoon van buiten de stad)<input name="external" maxlength="120"></label><label>Functie<input name="title" required maxlength="120"></label><label>Toelichting<textarea name="notes" maxlength="4000"></textarea></label>`}<h3>Ingangsdatum</h3>${dateFields('chancelleryEffective',pickerCurrentDate(system),system)}<p role="alert" id="registrationError"></p><div class="dialog-actions"><button type="button" id="cancelRegistration">Annuleren</button><button class="primary">Registreren</button></div></form>`;bindDateFields('chancelleryEffective');$('#cancelRegistration').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target),date=civilDateSnapshot(readDateFields('chancelleryEffective',system),system);if(date.day<1||date.day>currentEffectiveDay())throw Error('Kies een datum binnen de campagne.');if(transfer)registerPropertyTransfer(form.get('property'),form.get('person'),form.get('kind'),date.day);else{const personId=form.get('person'),personName=data.inwoners.find(n=>n.id===personId)?.name||String(form.get('external')).trim();if(!personName)throw Error('Vul een naam in.');(data.appointments??=[]).push({id:crypto.randomUUID(),personId,personName,title:String(form.get('title')).trim(),notes:String(form.get('notes')).trim(),day:date.day});persist()}dialog.close();render();toast('Registratie bewaard')}catch(error){$('#registrationError').textContent=error.message}};dialog.showModal()}
const render136=render;
render=function(){render136();if(view!=='finance'){$('#chancelleryThemes')?.remove();return}if(chancelleryTheme==='property'&&!['deeds'].includes(chancelleryPage)){const plots=data.map?.plots||[];$('#stats').innerHTML=[['Panden',data.locaties.length],['Percelen',plots.length],['Eigenaren',new Set([...data.locaties,...plots].map(r=>r.ownerId).filter(Boolean)).size],['Waarde van '+data.villageName,gp(data.locaties.reduce((sum,r)=>sum+assetFinance(r).build,0)+data.inwoners.reduce((sum,n)=>sum+residentFinance(n.id).plotCost,0))]].map(([label,value])=>`<div class="stat"><b>${esc(value)}</b><span>${esc(label)}</span></div>`).join('')}if(chancelleryTheme==='civil'&&['residents','appointments'].includes(chancelleryPage)){$('#stats').innerHTML=[['Inwoners',data.inwoners.length],['PC’s',data.inwoners.filter(n=>!n.npc).length],['NPC’s',data.inwoners.filter(n=>n.npc).length],['Benoemingen',(data.appointments||[]).length]].map(([label,value])=>`<div class="stat"><b>${esc(value)}</b><span>${esc(label)}</span></div>`).join('')}};

const updateCivilProfile137=updateCivilProfile;
updateCivilProfile=function(){updateCivilProfile137();if(editing?.type==='inwoners'&&!residentCivilRecords(editing.id).length&&!residentMarriages(editing.id).length)$('#residentMarriage')?.remove()};
const residentLedger137=residentLedger;
residentLedger=function(id){return residentLedger137(id).map(t=>{let outgoing=t.direction==='gedaan'||t.direction==='betalen';if(t.sourceKind==='transaction'){const own=(t.balanceDeltas||[]).filter(d=>d.id===id&&d.field==='bankGp');if(own.length)outgoing=own.reduce((sum,d)=>sum+d.amount,0)<0;else if(t.toResidentId===id&&t.residentId!==id)outgoing=false}let complete=t.sourceKind==='transaction'||t.sourceKind==='salary'?t.sourceKind==='transaction'||!!t.ownerCashApplied:!!(t.paid||t.received);return {...t,direction:outgoing?'Uitgave':'Inkomst',status:complete?(outgoing?'Betaald':'Ontvangen'):'Openstaand'}})};
function missingEntityData(){const issues=[];for(const {type,record:r}of datedEntities()){const fields=[];if(!String(r.name||'').trim())fields.push('Naam');const entries=data.entityHistory?.[type+':'+r.id]||[];if(!entries.length||entries[0].legacy)fields.push(type==='inwoners'?'Aankomstdatum':'Aanmaakdatum');if(type==='inwoners'){if(!String(r.kind||'').trim())fields.push('Beroep');if(!r.location)fields.push('Woonplek');else if(!['__lodging__','__unhoused_npc__'].includes(r.location)&&!data.locaties.some(p=>p.id===r.location))fields.push('Woonplek (verwijzing bestaat niet)');if(r.workplace&&r.workplace!=='__travel__'&&!data.locaties.some(p=>p.id===r.workplace))fields.push('Werkplek (verwijzing bestaat niet)')}else{if(!r.ownerId)fields.push('Eigenaar niet toegewezen');else if(!data.inwoners.some(n=>n.id===r.ownerId))fields.push('Eigenaar (verwijzing bestaat niet)');if(type==='locaties'&&!ensureFinance().catalog.some(p=>p.id===ensureFinance().assets[r.id]?.profile))fields.push('Regelprofiel')}if(fields.length)issues.push({type,id:r.id,name:r.name||'Zonder naam',fields})}return issues}
function openMissingEntityData(){let dialog=$('#missingEntityData');if(!dialog){dialog=document.createElement('dialog');dialog.id='missingEntityData';document.body.append(dialog)}const issues=missingEntityData();dialog.innerHTML=`<h2>Ontbrekende gegevens</h2><p>Controleer nog ontbrekende of voorlopige datums, namen, beroepen, woonplekken, eigenaren en regelprofielen. Een niet toegewezen eigenaar kan bewust zijn; optionele gegevens zoals portretten, beschrijvingen, werkplekken en huwelijken tellen niet als ontbrekend.</p><label>Onderdeel<select id="missingType"><option value="all">Alle onderdelen</option><option value="inwoners">Inwoners</option><option value="locaties">Panden</option><option value="plots">Percelen</option></select></label><p>${issues.length} onderdelen om te controleren</p>${chancelleryRows(['Onderdeel','Naam','Nog te controleren','Aanvullen'],issues.map((r,i)=>`<tr data-missing-type="${r.type}"><td>${{inwoners:'Inwoner',locaties:'Pand',plots:'Perceel'}[r.type]}</td><td>${esc(r.name)}</td><td>${r.fields.map(esc).join('<br>')}</td><td><button data-fill-missing="${i}">Gegevens</button> <button data-fill-date="${i}">Datum</button></td></tr>`))}<div class="form-actions"><button id="refreshMissing">Opnieuw controleren</button><button id="closeMissing">Sluiten</button></div>`;$('#missingType').onchange=e=>dialog.querySelectorAll('[data-missing-type]').forEach(row=>row.hidden=e.target.value!=='all'&&row.dataset.missingType!==e.target.value);dialog.querySelectorAll('[data-fill-missing]').forEach(b=>b.onclick=()=>{const r=issues[Number(b.dataset.fillMissing)];dialog.close();if(r.type==='plots')editPlot(r.id);else edit(r.type,r.id)});dialog.querySelectorAll('[data-fill-date]').forEach(b=>b.onclick=()=>{const r=issues[Number(b.dataset.fillDate)];dialog.close();openCreationDate137(r.type,r.id)});$('#refreshMissing').onclick=()=>openMissingEntityData();$('#closeMissing').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function setCreationDate137(type,id,day){if(!Number.isInteger(day)||day<1||day>currentEffectiveDay())throw Error('Kies een datum binnen de campagne.');captureEntityDates();const item=datedEntities().find(r=>r.type===type&&r.record.id===id);if(!item)throw Error('Onderdeel niet gevonden.');const key=type+':'+id,entries=data.entityHistory[key]??=[],first=entries[0];if(first){if(entries.slice(1).some(e=>e.day<day))throw Error('De aanmaakdatum moet vóór of op de eerste wijziging liggen.');first.day=day;first.legacy=false}else{const baseline=data.entityHistoryBaselines?.[key];entries.push({day,state:structuredClone(baseline?.state||item.record),finance:type==='locaties'?structuredClone(baseline?.finance||ensureFinance().assets[id]||{}):null,legacy:false})}if(data.entityHistoryBaselines?.[key])data.entityHistoryBaselines[key].day=day;persist()}
