// A personal employee wage changes payroll and operating costs, never the tariff itself.
function hasPersonalSalary(n){return n?.salaryOverrideGp!==undefined&&n.salaryOverrideGp!==null&&n.salaryOverrideGp!==''&&Number.isFinite(Number(n.salaryOverrideGp))&&Number(n.salaryOverrideGp)>=0}
function npcSalaryEmployment(n){if(!n?.npc)return null;const f=ensureFinance();for(const location of data.locaties){const rule=f.assets[location.id]||{},staff=f.staff.find(s=>s.id===rule.staff);if(rule.staffResidentId===n.id&&location.ownerId!==n.id&&n.workplace===location.id&&staff&&staff.id!=='none'&&!staff.ownerLevel)return {location,rule,staff}}return null}
function personalSalaryStaff(location,rule,standard){const employee=data.inwoners.find(n=>n.id===rule.staffResidentId);if(!employee?.npc||employee.id===location.ownerId||employee.workplace!==location.id||standard.id==='none'||standard.ownerLevel||!hasPersonalSalary(employee))return standard;return {...standard,wage:Number(employee.salaryOverrideGp),standardWage:Number(standard.wage),personalSalary:true}}
function personalSalaryFieldChanged(r){const field=$('#form')?.elements?.salaryOverrideGp;if(!field)return false;const next=field.value.trim()===''?null:Number(field.value),previous=hasPersonalSalary(r)?Number(r.salaryOverrideGp):null;return next!==previous}
function savePersonalSalaryField(r,form){if(!form.has('salaryOverrideGp'))return;const value=String(form.get('salaryOverrideGp')).trim();if(value===''){delete r.salaryOverrideGp;return}const amount=Number(value);if(Number.isFinite(amount)&&amount>=0)r.salaryOverrideGp=Math.round(amount*100)/100}
function addPersonalSalaryEditor(type,id){if(type!=='inwoners')return;const n=data.inwoners.find(n=>n.id===id),job=npcSalaryEmployment(n);if(!job)return;const period=calendarConfig().system==='harptos'?'tenday':'week',section=document.createElement('section');section.id='personalSalary';section.className='personal-salary';section.innerHTML=`<h3>Salaris als werknemer</h3><p>${esc(job.location.name)} · ${esc(job.staff.name)}</p><p>Standaardtarief: <b>${gp(job.staff.wage)} per ${period}</b></p><label>Persoonlijk salaris (gp per ${period})<input name="salaryOverrideGp" type="number" min="0" max="1000000000" step=".01" value="${hasPersonalSalary(n)?esc(n.salaryOverrideGp):''}" placeholder="Standaard: ${esc(job.staff.wage)}"></label><p class="field-help">Vul het volledige nieuwe salaris in. Leeg laten gebruikt het tarief. Bij een wijziging kies je de ingangsdatum. Het bedrag geldt voor salarisperiodes waarvan de einddatum op of na die datum valt; al betaalde salarissen blijven ongewijzigd. De loonsverhoging verandert het personeelsniveau en de opbrengstfactor niet.</p>`;$('#extra').append(section)}
