// Travel days and player wage agreements use the campaign calendar.
let financeEvaluationDay=null;
const withDatedState139=withDatedState;
withDatedState=function(day,fn){const previous=financeEvaluationDay;financeEvaluationDay=day;try{return withDatedState139(day,fn)}finally{financeEvaluationDay=previous}};
function residentIsTravelling(n,day=financeEvaluationDay??currentEffectiveDay()){if(!n)return false;const trips=(data.travelPeriods||[]).filter(t=>t.residentId===n.id);return trips.length?trips.some(t=>t.departureDay<=day&&(t.returnDay===null||day<t.returnDay)):n.workplace==='__travel__'}
function periodLodgingCost(id,week){const end=paymentPeriodEndDay(week),start=Math.max(1,end-paymentPeriodDays()+1);let total=0;for(let day=start;day<=end;day++)total+=withDatedState(day,()=>{const n=data.inwoners.find(n=>n.id===id);return n&&needsLodging(n)?lodgingRate():0});return Math.round(total*100)/100}
function saveTravelPeriod(residentId,departureDay,returnDay=null,id=null){if(!data.inwoners.some(n=>n.id===residentId))throw Error('Inwoner niet gevonden.');if(!Number.isInteger(departureDay)||departureDay<1||departureDay>currentEffectiveDay()||returnDay!==null&&(!Number.isInteger(returnDay)||returnDay<departureDay||returnDay>currentEffectiveDay()))throw Error('Kies geldige vertrek- en terugkomstdatums binnen de campagne.');const periods=data.travelPeriods||[];if(periods.some(t=>t.id!==id&&t.residentId===residentId&&departureDay<(t.returnDay??Infinity)&&(returnDay??Infinity)>t.departureDay))throw Error('Deze reis overlapt een bestaande reis.');const existing=id?periods.find(t=>t.id===id&&t.residentId===residentId):null;if(id&&!existing)throw Error('Reis niet gevonden.');const record={id:existing?.id||crypto.randomUUID(),residentId,departureDay,returnDay};if(existing)Object.assign(existing,record);else(data.travelPeriods??=[]).push(record);persist();prepareTimelinePayments();return record}
function openTravelEditor(residentId,id=null){const n=data.inwoners.find(n=>n.id===residentId);if(!n)return;const trip=data.travelPeriods?.find(t=>t.id===id),system=calendarConfig().system;let dialog=$('#travelEditor');if(!dialog){dialog=document.createElement('dialog');dialog.id='travelEditor';document.body.append(dialog)}dialog.innerHTML=`<form><h2>${trip?'Reis / terugkomst wijzigen':'Reis registreren'}</h2><p>${esc(n.name)}</p><h3>Vertrek</h3>${dateFields('travelDeparture',campaignDate(trip?.departureDay||currentEffectiveDay()),system)}<label><input type="checkbox" name="returned" ${trip?.returnDay!==null&&trip?.returnDay!==undefined?'checked':''}> Teruggekomen</label><div id="travelReturnFields"><h3>Terugkomst</h3>${dateFields('travelReturn',campaignDate(trip?.returnDay||currentEffectiveDay()),system)}</div><p class="field-help">Op de vertrekdatum vervallen de overnachtingskosten. De terugkomstdatum telt weer als een nacht in de stad. Al betaalde periodes worden niet automatisch teruggedraaid. Een geregistreerde terugkomst beëindigt de vrijstelling automatisch.</p><p role="alert"></p><div class="form-actions"><button type="button" id="cancelTravel">Annuleren</button><button class="primary">Reis bewaren</button></div></form>`;bindDateFields('travelDeparture');bindDateFields('travelReturn');const form=dialog.querySelector('form'),toggle=()=>$('#travelReturnFields').hidden=!form.elements.returned.checked;form.elements.returned.onchange=toggle;toggle();$('#cancelTravel').onclick=()=>dialog.close();form.onsubmit=e=>{e.preventDefault();try{const from=civilDateSnapshot(readDateFields('travelDeparture',system),system).day,to=form.elements.returned.checked?civilDateSnapshot(readDateFields('travelReturn',system),system).day:null;saveTravelPeriod(n.id,from,to,id);dialog.close();render();if($('#residentReport')?.open){$('#residentReport').close();openResidentReport(data.inwoners.find(p=>p.id===n.id))}toast('Vertrek en terugkomst bewaard.')}catch(error){dialog.querySelector('[role=alert]').textContent=error.message}};dialog.showModal()}
function playerWageAgreement(n){return !!n&&!n.npc&&!!n.employmentEmployerId&&n.employmentEmployerId!==n.id&&data.inwoners.some(p=>p.id===n.employmentEmployerId)&&n.employmentWageGp!==undefined&&Number.isFinite(Number(n.employmentWageGp))&&Number(n.employmentWageGp)>=0}
