function addPlayerEmploymentEditor(type,id){if(type!=='inwoners')return;const n=data.inwoners.find(n=>n.id===id);if(n?.npc)return;const period=calendarConfig().system==='harptos'?'tenday':'week';$('#extra').insertAdjacentHTML('beforeend',`<section class="personal-salary"><h3>Salarisafspraak als werknemer</h3><label>Werkgever<select name="employmentEmployerId"><option value="">Geen salarisafspraak</option>${data.inwoners.filter(p=>p.id!==id&&!p.npc).map(p=>`<option value="${esc(p.id)}" ${n?.employmentEmployerId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Afgesproken salaris (gp per ${period})<input name="employmentWageGp" type="number" min="0" max="1000000000" step=".01" value="${n?.employmentWageGp??''}"></label><p class="field-help">Kies de speler die het salaris betaalt. Bij een wijziging kies je een ingangsdatum. Betalen gebeurt via de bank bij Kanselarij → Financiën → Betalingen. Geen salarisafspraak beëindigt de afspraak vanaf de gekozen datum.</p></section>`);const employer=$('#form').elements.employmentEmployerId,amount=$('#form').elements.employmentWageGp;const configure=()=>{amount.required=!!employer.value;amount.disabled=!employer.value};employer.onchange=configure;const workplace=$('#form').elements.workplace;if(workplace)workplace.addEventListener('change',()=>{const owner=data.locaties.find(r=>r.id===workplace.value)?.ownerId;if(!employer.value&&owner&&owner!==id&&data.inwoners.some(p=>p.id===owner&&!p.npc))employer.value=owner;configure()});configure()}
