function createAcquisitionInvoice(type,record,amount){amount=Math.round(Number(amount)*100)/100;if(!Number.isFinite(amount)||amount<=0)return null;if(!data.inwoners.some(n=>n.id===record.ownerId))throw Error('Kies een eigenaar voor de rekening.');const f=ensureFinance();f.purchaseInvoices??=[];const propertyKey=type+':'+record.id;if(f.purchaseInvoices.some(p=>p.propertyKey===propertyKey&&!p.cancelled))return null;const invoice={id:crypto.randomUUID(),propertyKey,propertyName:record.name||(type==='plots'?plotLabel(record):'Pand'),residentId:record.ownerId,amount,label:(type==='plots'?'Aanschaf perceel — ':'Bouw / aanschaf pand — ')+(record.name||plotLabel(record)),campaignDay:entityCaptureDay??currentEffectiveDay(),paid:false,direction:'inbound'};f.purchaseInvoices.push(invoice);return invoice}
