function acquisitionChoice(registeredValue,price,free=false,invoice=true){const amount=free?0:Number(price);if(!free&&(price===null||price===undefined||String(price).trim()==='')||!Number.isFinite(amount)||amount<0||amount>1000000000)throw Error('Vul een geldige aankoopprijs in.');return {registeredValue:Math.round(Number(registeredValue||0)*100)/100,price:Math.round(amount*100)/100,free:!!free,invoiceRequested:!!invoice&&amount>0&&!free}}
function purchaseEditorMarkup(prefix,billId,billName){return `<section class="purchase-editor"><h3>Aankoop en rekening</h3><p>Geregistreerde waarde: <b id="${prefix}Value">—</b></p><label>Aankoopprijs (gp)<input type="number" id="${prefix}Price" name="${prefix}Price" min="0" max="1000000000" step=".01" required></label><label class="purchase-option"><input type="checkbox" id="${prefix}Free" name="${prefix}Free"> Gratis verstrekken</label><label class="purchase-option"><input type="checkbox" id="${billId}" name="${billName}" checked> Rekening aanmaken</label><p class="field-help">De aankoopprijs mag afwijken van de geregistreerde waarde. De rekening wordt pas bij aanmaken toegevoegd aan Betalingen; er wordt nog niets afgeschreven.</p><p id="${prefix}Summary" class="purchase-summary" aria-live="polite"></p></section>`}
function bindPurchaseEditor(prefix,billId,submit,owner,getValue,defaultInvoice=true){const price=$('#'+prefix+'Price'),free=$('#'+prefix+'Free'),bill=$('#'+billId),value=$('#'+prefix+'Value'),summary=$('#'+prefix+'Summary');let automatic=true,lastPrice=0,lastBill=defaultInvoice;bill.checked=defaultInvoice;const update=()=>{const registered=Math.round(Number(getValue()||0)*100)/100;value.textContent=gp(registered);if(automatic&&!free.checked)price.value=registered;price.disabled=free.checked;price.required=!free.checked;bill.disabled=free.checked||Number(price.value)===0;owner.required=!!bill.checked&&!bill.disabled;const amount=free.checked?0:Number(price.value);summary.textContent=free.checked?'Gratis verstrekt · geen rekening.':bill.checked&&amount>0?'Er wordt een rekening aangemaakt voor '+gp(amount)+'.':'Er wordt geen rekening aangemaakt.';submit.textContent=(prefix==='buildingPurchase'?'Pand':'Perceel')+' aanmaken · '+(free.checked?'gratis':bill.checked&&amount>0?'rekening '+gp(amount):'zonder rekening')};price.oninput=()=>{automatic=false;update()};bill.onchange=()=>{lastBill=bill.checked;update()};free.onchange=()=>{if(free.checked){lastPrice=Number(price.value||0);lastBill=bill.checked;price.value=0;bill.checked=false}else{price.value=automatic?getValue():lastPrice;bill.checked=lastBill}update()};update();return update}
function addBuildingPurchaseEditor(){const form=$('#form'),kind=form.elements.kind,owner=form.elements.ownerId;$('#extra').insertAdjacentHTML('beforeend',purchaseEditorMarkup('buildingPurchase','billNewBuilding','billCreation'));const getValue=()=>ensureFinance().catalog.find(p=>p.id===kind.value)?.cost||0,profile=ensureFinance().catalog.find(p=>p.id===kind.value),defaultInvoice=true;const update=bindPurchaseEditor('buildingPurchase','billNewBuilding',form.querySelector('.form-actions button.primary'),owner,getValue,defaultInvoice);kind.addEventListener('change',update);const oldValue=$('#extra .building-value');if(oldValue)oldValue.remove()}
function proposedPlotValue(rect,ownerId){const f=ensureFinance(),existing=(data.map?.plots||[]).filter(p=>p.ownerId===ownerId&&ownerId).flatMap(plotCells),before=new Set(existing.map(c=>c.join(','))),after=new Set(before);for(const cell of plotCells(rect||{}))after.add(cell.join(','));return Math.max(0,plotPurchaseValue(after.size/f.startPlotCells,f.plotPrices)-plotPurchaseValue(before.size/f.startPlotCells,f.plotPrices))}
