function townMetricChanges(key,fromDay,toDay){const before=fromDay===null?[]:townMetricContributions(fromDay,key),after=townMetricContributions(toDay,key),oldMap=new Map(before.map(r=>[r.id,r])),newMap=new Map(after.map(r=>[r.id,r]));const rows=[...new Set([...oldMap.keys(),...newMap.keys()])].map(id=>{const old=oldMap.get(id),next=newMap.get(id),previous=old?.amount||0,current=next?.amount||0;return {id,label:next?.label||old.label,before:previous,after:current,delta:Math.round((current-previous)*100)/100,reason:old&&next?(old.reason===next.reason?next.reason:old.reason+' → '+next.reason):next?'Toegevoegd · '+next.reason:'Niet meer aanwezig · '+old.reason}});return {rows:rows.sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)||a.label.localeCompare(b.label,'nl')),before:before.reduce((sum,r)=>sum+r.amount,0),after:after.reduce((sum,r)=>sum+r.amount,0)}}
function townMetricRecordedEvents(key,fromDay,toDay){if(fromDay===null)return [];const events=[],fields=key==='population'?['npc','staff','staffResidentId']:key==='value'?['ownerId','cells','profile','modules','costOverride']:key==='income'?['ownerId','location','workplace','profile','staff','ownerWorks','modules','incomeOverride']:['ownerId','location','workplace','profile','staff','staffResidentId','ownerWorks','modules','salaryOverrideGp','employmentEmployerId','employmentWageGp','upkeepOverride'];for(const [entityKey,entries]of Object.entries(data.entityHistory||{})){if(!['inwoners','locaties','plots'].includes(entityKey.split(':')[0]))continue;entries.forEach((entry,i)=>{if(entry.day<=fromDay||entry.day>toDay)return;const previous=historyPrevious(entries,i,data.entityHistoryBaselines?.[entityKey]);const initial=i===0&&!data.entityHistoryBaselines?.[entityKey];const changed=fields.some(field=>JSON.stringify(previous.state?.[field])!==JSON.stringify(entry.state?.[field])||JSON.stringify(previous.finance?.[field])!==JSON.stringify(entry.finance?.[field]));if(!initial&&!changed)return;events.push({day:entry.day,label:entry.state.name||'Perceel',description:initial?'Registratie toegevoegd':describeEntityChange(previous,entry)})})}if(['income','cost','profit'].includes(key))for(const trip of data.travelPeriods||[]){const name=data.inwoners.find(n=>n.id===trip.residentId)?.name||'Inwoner';if(trip.departureDay>fromDay&&trip.departureDay<=toDay)events.push({day:trip.departureDay,label:name,description:'Vertrokken op reis · geen overnachtingskosten tijdens de reis'});if(trip.returnDay!==null&&trip.returnDay>fromDay&&trip.returnDay<=toDay)events.push({day:trip.returnDay,label:name,description:'Teruggekomen · automatische overnachtingen kunnen weer gelden'})}return events.sort((a,b)=>a.day-b.day||a.label.localeCompare(b.label,'nl'))}
function bindTownHistoryDetails(section){section.querySelectorAll('[data-chart-metric]').forEach(card=>{card.onclick=()=>openTownMetricDetails(card.dataset.chartMetric);card.onkeydown=e=>{if(e.target===card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openTownMetricDetails(card.dataset.chartMetric)}}});section.querySelectorAll('[data-history-metric]').forEach(point=>{const open=e=>{e.stopPropagation();openTownMetricDetails(point.dataset.historyMetric,Number(point.dataset.historyDay))};point.onclick=open;point.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(e)}}})}
function openTownMetricDetails(key,selectedDay=null,fromOverride=undefined,showAll=false){if(!chartMetricLabels[key])return;const history=timelineTownMetrics();if(!history.length)return;const selected=history.find(p=>p.day===selectedDay)||history.at(-1),index=history.indexOf(selected),fromDay=fromOverride===undefined?(index>0?history[index-1].day:null):fromOverride,toDay=selected.day;let dialog=$('#townMetricDetails');if(!dialog){dialog=document.createElement('dialog');dialog.id='townMetricDetails';document.body.append(dialog)}const changes=townMetricChanges(key,fromDay,toDay),visible=changes.rows.filter(r=>showAll?Math.abs(r.before)>.005||Math.abs(r.after)>.005:fromDay===null?Math.abs(r.after)>.005:Math.abs(r.delta)>.005),delta=Math.round((changes.after-changes.before)*100)/100,format=value=>chartMetricFormat(key,value),signed=value=>(value>0?'+':'')+format(value),events=townMetricRecordedEvents(key,fromDay,toDay),unit=['income','cost','profit'].includes(key)?' / '+(calendarConfig().system==='harptos'?'tenday':'week'):'';dialog.innerHTML=`<h2>${esc(chartMetricLabels[key]+unit)} · wijzigingen</h2><div class="chart-period-selectors"><label>Van<select id="chartDetailsFrom"><option value="baseline" ${fromDay===null?'selected':''}>Beginstand bekijken</option>${history.filter(p=>p.day<toDay).map(p=>`<option value="${p.day}" ${p.day===fromDay?'selected':''}>${esc(calendarLabel(p.day))}</option>`).join('')}</select></label><label>Naar<select id="chartDetailsTo">${history.map(p=>`<option value="${p.day}" ${p.day===toDay?'selected':''}>${esc(calendarLabel(p.day))}</option>`).join('')}</select></label></div><p>${esc(selected.eventNames||'Tijdlijnmoment')}</p><div class="chart-change-summary">${fromDay===null?'':`<div><small>${esc(calendarLabel(fromDay))}</small><b>${esc(format(changes.before))}</b></div>`}<div><small>${esc(calendarLabel(toDay))}</small><b>${esc(format(changes.after))}</b></div><div><small>${fromDay===null?'Eerste meetpunt':'Verschil'}</small><b>${fromDay===null?'Geen eerdere vergelijking':esc(signed(delta))}</b></div></div><h3>${fromDay===null?'Opbouw van de waarde':'Wat verklaart het verschil?'}</h3><label class="chart-show-unchanged"><input type="checkbox" id="chartShowUnchanged" ${showAll?'checked':''}> Ook ongewijzigde onderdelen tonen</label>${chancelleryRows(fromDay===null?['Onderdeel','Bedrag','Toelichting']:['Onderdeel','Vorige waarde','Nieuwe waarde','Verschil','Toelichting'],visible.map(r=>`<tr><td>${esc(r.label)}</td>${fromDay===null?'':`<td>${esc(format(r.before))}</td>`}<td>${esc(format(r.after))}</td>${fromDay===null?'':`<td>${esc(signed(r.delta))}</td>`}<td>${esc(r.reason)}</td></tr>`))}${!visible.length?'<p>Geen veranderingen in de opbouw van deze grafiek tussen de gekozen datums.</p>':''}${events.length?'<h3>Vastgelegde wijzigingen in deze periode</h3><ul class="chart-event-list">'+events.map(e=>'<li><b>'+esc(calendarLabel(e.day))+' · '+esc(e.label)+'</b><br>'+esc(e.description)+'</li>').join('')+'</ul>':''}<p class="field-help">De grafiek toont de stand per tijdlijndatum, gebaseerd op geregistreerde ingangsdatums en de huidige tarieven. Een betaling in het kasboek verandert deze verwachte bedragen niet.${key==='profit'?' Inkomsten en kosten tellen hier met tegengesteld teken mee.':''}</p><div class="form-actions"><button id="closeTownMetricDetails">Sluiten</button></div>`;$('#chartDetailsFrom').onchange=e=>openTownMetricDetails(key,toDay,e.target.value==='baseline'?null:Number(e.target.value),showAll);$('#chartDetailsTo').onchange=e=>{const nextDay=Number(e.target.value),validFrom=fromDay!==null&&fromDay<nextDay?fromDay:undefined;openTownMetricDetails(key,nextDay,validFrom,showAll)};$('#chartShowUnchanged').onchange=e=>openTownMetricDetails(key,toDay,fromDay,e.target.checked);$('#closeTownMetricDetails').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
